// ---- Routines ----

async function PICK_ONE(tbl) {
  let length = 0, cnt = 0, rnd = 0, msg = 0, rfrob = 0;
  length = get(tbl, 0);
  cnt = get(tbl, 1);
  length = length - 1;
  tbl = tbl + 2;
  rfrob = tbl + (cnt * 2);
  rnd = random(length - cnt);
  msg = get(rfrob, rnd);
  put(rfrob, rnd, get(rfrob, 1));
  put(rfrob, 1, msg);
  cnt = cnt + 1;
  if (cnt == length) {
    cnt = 0;
  }
  put(tbl, 0, cnt);
  return msg;
}

async function APRINT(obj) {
  if (hasFlag(obj, NARTICLEBIT) || (obj == PANTS || obj == RUM || obj == SALTS)) {
    tell(" ");
  } else if (hasFlag(obj, VOWELBIT)) {
    tell(" an ");
  } else {
    tell(" a ");
  }
  return printD(obj);
}

async function TPRINT(obj) {
  if (hasFlag(obj, NARTICLEBIT)) {
    tell(" ");
  } else {
    tell(" the ");
  }
  return printD(obj);
}

async function CTPRINT(obj) {
  tell("The ");
  return printD(obj);
}

async function TPRINT_PRSO() {
  return await TPRINT(g.PRSO);
}

async function TPRINT_PRSI() {
  return await TPRINT(g.PRSI);
}

async function ARPRINT(obj) {
  await APRINT(obj);
  tell(S(g.PCR));
  return true;
}

async function TRPRINT(obj) {
  await TPRINT(obj);
  tell(S(g.PCR));
  return true;
}

async function GO() {
  restart: for (;;) {
    tell(">SHOOT THE PIRATE\nTrembling, you fire the heavy arquebus. You hear its loud report over the roaring wind, yet the dark figure still approaches. The gun falls from your nerveless hands.\n   \"You won't kill me,\" he says, stepping over the weapon. \"Not when I am the only protection you have from Jean Lafond.\"\n   ", S(g.NUTBROWN), "Lips curving,", S(g.EYES_RAKE), ". You are intensely aware of the strength of his hard seaworn body, of the deep sea blue of his eyes. And then his mouth is on yours, lips parted, demanding, and you arch into his kiss...\n   He presses you against him, head bent. \"But who, my dear,\" he whispers into your hair, \"will protect you from me?\"\n");
    tell("\n", S(g.HIT_RETURN), "begin.]\n");
    await read(g.P_INBUF, g.P_LEXV);
    await CLEAR_SCREEN(11);
    g.HERE = CABIN;
    await V_VERSION();
    crlf();
    tell("LATE ONE SPRING NIGHT IN THE WEST INDIES...\n\n   A crash overhead! Pirates are boarding the Lafond Deux! The first mate hurries you into Captain Davis's cabin.\n   \"Good, you brought the girl,\" Davis smirks. \"She'll keep the pirates busy. She was only a tool of Lafond's, anyway. Let me just find that cof--\" A man on deck screams in agony and Davis starts. \"Let's go.\" The captain thrusts you on the bed and walks out, locking the door.\n   His laugh echoes. \"Best get comfortable, girl. You're likely to be there for the rest of your life.\"\n\n");
    await V_LOOK();
    await MAIN_LOOP();
    continue restart;
  }
}

async function CLEAR_SCREEN(cnt = 24) {
  for (;;) {
    crlf();
    cnt = cnt - 1;
    if (cnt == 0) {
      return true;
    }
  }
}

async function MAIN_LOOP() {
  let trash = 0;
  for (;;) {
    trash = await MAIN_LOOP_1();
  }
}

async function MAIN_LOOP_1() {
  let icnt = 0, ocnt = 0, num = 0, cnt = 0, obj = false, tbl = 0, v_ = 0, ptbl = true, obj1 = 0, tmp = 0, onum = 0;
  if (g.P_WON = await PARSER()) {
    icnt = getb(g.P_PRSI, g.P_MATCHLEN);
    ocnt = getb(g.P_PRSO, g.P_MATCHLEN);
    if (g.P_IT_OBJECT && (await ACCESSIBLE$(g.P_IT_OBJECT))) {
      tmp = false;
      loop1: for (;;) {
        if ((cnt = cnt + 1) > icnt) {
          break loop1;
        } else {
          if (eq(getb(g.P_PRSI, cnt), IT)) {
            if (await TOO_DARK_FOR_IT$()) {
              return true;
            }
            putb(g.P_PRSI, cnt, g.P_IT_OBJECT);
            tmp = true;
            break loop1;
          }
        }
      }
      if (!tmp) {
        cnt = 0;
        loop2: for (;;) {
          if ((cnt = cnt + 1) > ocnt) {
            break loop2;
          } else {
            if (eq(getb(g.P_PRSO, cnt), IT)) {
              if (await TOO_DARK_FOR_IT$()) {
                return true;
              }
              putb(g.P_PRSO, cnt, g.P_IT_OBJECT);
              break loop2;
            }
          }
        }
      }
      cnt = 0;
    }
    onum = getb(g.P_SYNTAX, P_SBITS) & P_SONUMS;
    num = (ocnt == 0) || ((icnt == 0) && (onum == 2)) ? 0 : (ocnt > 1 ? (tbl = g.P_PRSO, icnt == 0 ? (obj = false) : (obj = getb(g.P_PRSI, 1)), ocnt) : (icnt > 1 ? (ptbl = false, tbl = g.P_PRSI, obj = getb(g.P_PRSO, 1), icnt) : 1));
    if (!obj && (icnt == 1)) {
      obj = getb(g.P_PRSI, 1);
    }
    if (g.PRSA == V.WALK) {
      v_ = await PERFORM_PRSA(g.PRSO);
    } else if (num == 0) {
      if ((getb(g.P_SYNTAX, P_SBITS) & P_SONUMS) == 0) {
        v_ = await PERFORM_PRSA();
        g.PRSO = false;
      } else {
        tell("There isn't anything to ");
        tmp = get(g.P_ITBL, P_VERBN);
        if (isVerb(V.TELL)) {
          tell("talk to");
        } else if (g.P_OFLAG || g.P_MERGED) {
          printB(get(tmp, 0));
        } else {
          await WORD_PRINT(getb(tmp, 2), getb(tmp, 3));
        }
        tell("!\n");
        v_ = false;
        await STOP();
      }
    } else {
      g.P_NOT_HERE = 0;
      g.P_MULT = false;
      if (num > 1) {
        g.P_MULT = true;
      }
      tmp = false;
      loop3: for (;;) {
        if ((cnt = cnt + 1) > num) {
          if (g.P_NOT_HERE > 0) {
            tell("[The ");
            if (!(g.P_NOT_HERE == num)) {
              tell("other ");
            }
            tell("object");
            if (!(g.P_NOT_HERE == 1)) {
              tell("s");
            }
            tell(" that you mentioned ");
            if (!(g.P_NOT_HERE == 1)) {
              tell("are");
            } else {
              tell("is");
            }
            tell("n't here.]\n");
          } else if (!tmp) {
            await REFERRING();
          }
          break loop3;
        } else {
          if (ptbl) {
            obj1 = getb(g.P_PRSO, cnt);
          } else {
            obj1 = getb(g.P_PRSI, cnt);
          }
          g.PRSO = ptbl ? obj1 : obj;
          g.PRSI = ptbl ? obj : obj1;
          if ((num > 1) || eq(get(get(g.P_ITBL, P_NC1), 0), W.ALL, W.EVERYT)) {
            if (await DONT_ALL(obj1)) {
              continue loop3;
            } else {
              if (obj1 == IT) {
                tell(D(g.P_IT_OBJECT));
              } else if (obj1 == HIM) {
                tell(D(g.P_HIM_OBJECT));
              } else if (obj1 == HER) {
                tell(D(g.P_HER_OBJECT));
              } else {
                tell(D(obj1));
              }
              tell(": ");
            }
          }
          tmp = true;
          v_ = await PERFORM_PRSA(g.PRSO, g.PRSI);
          if (v_ == M_FATAL) {
            break loop3;
          }
        }
      }
    }
    if (v_ == M_FATAL) {
      g.P_CONT = false;
    }
    if ((await CLOCKER_VERB$()) && !(isVerb(V.TELL)) && g.P_WON) {
      v_ = await apply(getProp(g.HERE, P.ACTION), M_END);
    }
  } else {
    g.P_CONT = false;
  }
  if (g.P_WON) {
    if (await CLOCKER_VERB$()) {
      v_ = await CLOCKER();
    }
    g.PRSA = false;
    g.PRSO = false;
    return g.PRSI = false;
  } else {
    return false;
  }
}

async function TOO_DARK_FOR_IT$() {
  if (!g.LIT && !(await HELD$(g.P_IT_OBJECT, g.WINNER)) && !(loc(g.WINNER) == g.P_IT_OBJECT)) {
    tell(S(g.TOO_DARK), "\n");
    return true;
  } else {
    return false;
  }
}

async function DONT_ALL(obj1) {
  let l = loc(obj1);
  if (obj1 == NOT_HERE_OBJECT) {
    g.P_NOT_HERE = g.P_NOT_HERE + 1;
    return true;
  } else if (isVerb(V.TAKE) && g.PRSI && !(loc(g.PRSO) == g.PRSI)) {
    return true;
  } else if (!(await ACCESSIBLE$(obj1))) {
    return true;
  } else if (g.P_GETFLAGS == P_ALL) {
    if (g.PRSI && (g.PRSO == g.PRSI)) {
      return true;
    } else if (isVerb(V.TAKE)) {
      if (!(hasFlag(obj1, TAKEBIT)) && !(hasFlag(obj1, TRYTAKEBIT))) {
        return true;
      } else if (!(l == g.WINNER || l == g.HERE || l == g.PRSI) && !(l == loc(g.WINNER))) {
        if (hasFlag(l, SURFACEBIT) && !(hasFlag(l, TAKEBIT))) {
          return false;
        } else {
          return true;
        }
      } else if (obj1 == BOOKS_GLOBAL || obj1 == POWER) {
        return true;
      } else if (!g.PRSI && (await HELD$(g.PRSO))) {
        return true;
      } else {
        return false;
      }
    } else if (isVerb(V.DROP, V.PUT, V.PUT_ON, V.GIVE, V.SGIVE) && !(loc(obj1) == g.WINNER)) {
      return true;
    } else if (isVerb(V.PUT, V.PUT_ON) && !(loc(g.PRSO) == g.WINNER) && (await HELD$(g.PRSO, g.PRSI))) {
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function CLOCKER_VERB$() {
  if (isVerb(V.VERSION, V.HELP, V.$RECORD, V.$UNRECORD, V.$COMMAND, V.$RANDOM, V.SAVE, V.RESTORE, V.RESTART, V.QUIT, V.SCRIPT, V.UNSCRIPT, V.BRIEF, V.SUPER_BRIEF, V.VERBOSE, V.SCORE)) {
    return false;
  } else {
    return true;
  }
}

async function FAKE_ORPHAN(it_was_used = false) {
  let tmp = 0;
  await ORPHAN(g.P_SYNTAX, false);
  tmp = get(g.P_OTBL, P_VERBN);
  tell("[Be specific: Wh");
  if (it_was_used) {
    tell("at object");
  } else {
    tell("o");
  }
  tell(S(DO_YOU_WANT));
  if (tmp == 0) {
    tell("tell");
  } else if (getb(g.P_VTBL, 2) == 0) {
    printB(get(tmp, 0));
  } else {
    await WORD_PRINT(getb(tmp, 2), getb(tmp, 3));
    putb(g.P_VTBL, 2, 0);
  }
  g.P_OFLAG = true;
  g.P_WON = false;
  await PREP_PRINT(getb(g.P_SYNTAX, P_SPREP1));
  tell("?]\n");
  return true;
}

async function PERFORM_PRSA(o = false, i = false) {
  await PERFORM(g.PRSA, o, i);
  return true;
}

async function PERFORM(a_, o = false, i = false) {
  let v_ = 0, oa = 0, oo = 0, oi = 0;
  oa = g.PRSA;
  oo = g.PRSO;
  oi = g.PRSI;
  g.PRSA = a_;
  if ((IT == o || IT == i) && !(a_ == V.WALK)) {
    if (await VISIBLE$(g.P_IT_OBJECT)) {
      if (IT == o) {
        o = g.P_IT_OBJECT;
      } else {
        i = g.P_IT_OBJECT;
      }
    } else {
      if (!i) {
        await FAKE_ORPHAN(true);
      } else {
        await REFERRING();
      }
      return M_FATAL;
    }
  }
  if ((HIM == o || HIM == i) && !(a_ == V.WALK)) {
    if (await VISIBLE$(g.P_HIM_OBJECT)) {
      if (HIM == o) {
        o = g.P_HIM_OBJECT;
      } else {
        i = g.P_HIM_OBJECT;
      }
    } else {
      if (!i) {
        await FAKE_ORPHAN();
      } else {
        await REFERRING(true);
      }
      return M_FATAL;
    }
  }
  if ((HER == o || HER == i) && !(a_ == V.WALK)) {
    if (await VISIBLE$(g.P_HER_OBJECT)) {
      if (HER == o) {
        o = g.P_HER_OBJECT;
      } else {
        i = g.P_HER_OBJECT;
      }
    } else {
      if (!i) {
        await FAKE_ORPHAN();
      } else {
        await REFERRING(true);
      }
      return M_FATAL;
    }
  }
  g.PRSO = o;
  g.PRSI = i;
  if ((!(a_ == V.WALK) && (NOT_HERE_OBJECT == g.PRSO || NOT_HERE_OBJECT == g.PRSI) && (v_ = (await D_APPLY("Not Here", NOT_HERE_OBJECT_F.id))))) {
    g.P_WON = false;
  } else {
    o = g.PRSO;
    i = g.PRSI;
    await THIS_IS_IT(g.PRSI);
    await THIS_IS_IT(g.PRSO);
    if ((v_ = (await D_APPLY("Actor", getProp(g.WINNER, P.ACTION))))) {
    } else if ((v_ = (await D_APPLY("M-Beg", getProp(loc(g.WINNER), P.ACTION), M_BEG)))) {
    } else if ((v_ = (await D_APPLY("Preaction", get(g.PREACTIONS, a_))))) {
    } else if ((i && (v_ = (await D_APPLY("PRSI", getProp(i, P.ACTION)))))) {
    } else if ((o && !(a_ == V.WALK) && (v_ = (await D_APPLY("PRSO", getProp(o, P.ACTION)))))) {
    } else if (v_ = await D_APPLY(false, get(g.ACTIONS, a_))) {
    }
  }
  g.PRSA = oa;
  g.PRSO = oo;
  g.PRSI = oi;
  return v_;
}

async function D_APPLY(str, fcn, foo = false) {
  let res = 0;
  if (!fcn) {
    return false;
  } else {
    res = foo ? (await apply(fcn, foo)) : (await apply(fcn));
    return res;
  }
}

async function DEQUEUE(rtn) {
  if (rtn = await QUEUED$(rtn)) {
    return put(rtn, C_RTN, 0);
  } else {
    return false;
  }
}

async function QUEUED$(rtn) {
  let c_ = 0, e = 0;
  e = g.C_TABLE + C_TABLELEN;
  c_ = g.C_TABLE + g.C_INTS;
  for (;;) {
    if (c_ == e) {
      return false;
    } else if (eq(get(c_, C_RTN), rtn)) {
      if (get(c_, C_TICK) == 0) {
        return false;
      } else {
        return c_;
      }
    }
    c_ = c_ + C_INTLEN;
  }
}

async function RUNNING$(rtn) {
  let c_ = 0;
  if ((c_ = await QUEUED$(rtn)) && !(get(c_, C_TICK) > 1)) {
    return true;
  } else {
    return false;
  }
}

async function QUEUE(rtn, tick) {
  let c_ = 0, e = 0, int = false;
  e = g.C_TABLE + C_TABLELEN;
  c_ = g.C_TABLE + g.C_INTS;
  loop1: for (;;) {
    if (c_ == e) {
      if (int) {
        c_ = int;
      } else {
        if (g.C_INTS < C_INTLEN) {
          tell("**Too many ints!**\n");
        }
        g.C_INTS = g.C_INTS - C_INTLEN;
        if (g.C_INTS < g.C_MAXINTS) {
          g.C_MAXINTS = g.C_INTS;
        }
        int = g.C_TABLE + g.C_INTS;
      }
      put(int, C_RTN, rtn);
      break loop1;
    } else if (eq(get(c_, C_RTN), rtn)) {
      int = c_;
      break loop1;
    } else if (get(c_, C_RTN) == 0) {
      int = c_;
    }
    c_ = c_ + C_INTLEN;
  }
  if (g.CLOCK_HAND && (int > g.CLOCK_HAND)) {
    tick = -(tick + 3);
  }
  put(int, C_TICK, tick);
  return int;
}

async function CLOCKER() {
  let e = 0, tick = 0, rtn = 0, flg = false, q$ = false, owinner = 0;
  if (g.CLOCK_WAIT) {
    g.CLOCK_WAIT = false;
    return false;
  }
  g.CLOCK_HAND = g.C_TABLE + g.C_INTS;
  e = g.C_TABLE + C_TABLELEN;
  owinner = g.WINNER;
  g.WINNER = PROTAGONIST;
  for (;;) {
    if (g.CLOCK_HAND == e) {
      g.CLOCK_HAND = e;
      g.MOVES = g.MOVES + 1;
      g.WINNER = owinner;
      return flg;
    } else if (!(get(g.CLOCK_HAND, C_RTN) == 0)) {
      tick = get(g.CLOCK_HAND, C_TICK);
      if (tick < (-1)) {
        put(g.CLOCK_HAND, C_TICK, (-tick) - 3);
        q$ = g.CLOCK_HAND;
      } else if (!(tick == 0)) {
        if (tick > 0) {
          tick = tick - 1;
          put(g.CLOCK_HAND, C_TICK, tick);
        }
        if (!(tick == 0)) {
          q$ = g.CLOCK_HAND;
        }
        if (!(tick > 0)) {
          rtn = get(g.CLOCK_HAND, C_RTN);
          if (tick == 0) {
            put(g.CLOCK_HAND, C_RTN, 0);
          }
          if (await apply(rtn)) {
            flg = true;
          }
          if (!q$ && !(get(g.CLOCK_HAND, C_RTN) == 0)) {
            q$ = true;
          }
        }
      }
    }
    g.CLOCK_HAND = g.CLOCK_HAND + C_INTLEN;
    if (!q$) {
      g.C_INTS = g.C_INTS + C_INTLEN;
    }
  }
}

async function THIS_IS_IT(obj) {
  if (!obj || (isVerb(V.WALK) && (g.PRSO == obj)) || (obj == PROTAGONIST) || (obj == NOT_HERE_OBJECT || obj == ME || obj == GLOBAL_ROOM)) {
    return true;
  } else if (hasFlag(obj, FEMALEBIT)) {
    return g.P_HER_OBJECT = obj;
  } else if (hasFlag(obj, ACTORBIT)) {
    return g.P_HIM_OBJECT = obj;
  } else {
    return g.P_IT_OBJECT = obj;
  }
}

async function OOPS_WARNING(str) {
  tell("[Warning: there are too many ", S(str), " after OOPS.]\n");
  return true;
}

async function PARSER() {
  let ptr = P_LEXSTART, wrd = 0, val = 0, verb = false, omerged = 0, owinner = 0, olen = 0, len = 0, dir = false, nw = 0, lw = 0, cnt = (-1);
  let $1;
  loop1: for (;;) {
    if ((cnt = cnt + 1) > P_ITBLLEN) {
      break loop1;
    } else {
      if (!g.P_OFLAG) {
        put(g.P_OTBL, cnt, get(g.P_ITBL, cnt));
      }
      put(g.P_ITBL, cnt, 0);
    }
  }
  omerged = g.P_MERGED;
  owinner = g.WINNER;
  g.P_ADVERB = false;
  g.P_MERGED = false;
  g.P_END_ON_PREP = false;
  putb(g.P_PRSO, g.P_MATCHLEN, 0);
  putb(g.P_PRSI, g.P_MATCHLEN, 0);
  putb(g.P_BUTS, g.P_MATCHLEN, 0);
  if (!g.QUOTE_FLAG && (g.WINNER != PROTAGONIST)) {
    g.WINNER = PROTAGONIST;
    if (!(hasFlag(loc(g.WINNER), VEHBIT))) {
      g.HERE = loc(g.WINNER);
    }
    g.LIT = await LIT$(g.HERE);
  }
  if (g.RESERVE_PTR) {
    ptr = g.RESERVE_PTR;
    await STUFF(g.P_LEXV, g.RESERVE_LEXV);
    await INBUF_STUFF(g.P_INBUF, g.RESERVE_INBUF);
    if (!(g.VERBOSITY == 0) && (PROTAGONIST == g.WINNER)) {
      crlf();
    }
    g.RESERVE_PTR = false;
    g.P_CONT = false;
  } else if (g.P_CONT) {
    ptr = g.P_CONT;
    if (!(g.VERBOSITY == 0) && (PROTAGONIST == g.WINNER)) {
      crlf();
    }
    g.P_CONT = false;
  } else {
    g.WINNER = PROTAGONIST;
    g.QUOTE_FLAG = false;
    if (!(hasFlag(loc(g.WINNER), VEHBIT))) {
      g.HERE = loc(g.WINNER);
    }
    g.LIT = await LIT$(g.HERE);
    if (!(g.VERBOSITY == 0)) {
      crlf();
    }
    tell(">");
    await read(g.P_INBUF, g.P_LEXV);
    olen = getb(g.P_LEXV, P_LEXWORDS);
  }
  g.P_LEN = getb(g.P_LEXV, P_LEXWORDS);
  if (g.P_LEN == 0) {
    tell("[Prithee, pardon?]\n");
    return false;
  } else if (eq(get(g.P_LEXV, ptr), W.OOPS)) {
    if (eq(get(g.P_LEXV, ptr + P_LEXELEN), W.PERIOD, W.COMMA)) {
      ptr = ptr + P_LEXELEN;
      g.P_LEN = g.P_LEN - 1;
    }
    if (!(g.P_LEN > 1)) {
      (await CANT_USE_THAT_WAY("OOPS"));
      return false;
    } else if (val = get(g.OOPS_TABLE, O_PTR)) {
      len = 2 * getb(g.AGAIN_LEXV, 0);
      cnt = g.P_LEN - 2;
      if (len < (val + (P_LEXELEN * cnt))) {
        cnt = div(len - val, P_LEXELEN);
        (await OOPS_WARNING("words"));
      }
      if (!(cnt == 0)) {
        len = getb(g.AGAIN_LEXV, P_LEXWORDS);
        putb(g.AGAIN_LEXV, P_LEXWORDS, len + cnt);
        cnt = P_LEXELEN * cnt;
        len = P_LEXELEN * len;
        loop2: for (;;) {
          put(g.AGAIN_LEXV, cnt + len, get(g.AGAIN_LEXV, len));
          if (--len < val) {
            break loop2;
          }
        }
      }
      cnt = g.P_LEN;
      loop3: for (;;) {
        if (--cnt < 1) {
          break loop3;
        }
        ptr = ptr + P_LEXELEN;
        put(g.AGAIN_LEXV, val, get(g.P_LEXV, ptr));
        wrd = (ptr * P_LEXELEN) + 2;
        if ((await INBUF_ADD(getb(g.P_LEXV, wrd), getb(g.P_LEXV, wrd + 1), (val * P_LEXELEN) + 3)) == 0) {
          (await OOPS_WARNING("letters"));
          break loop3;
        }
        val = val + P_LEXELEN;
      }
      g.WINNER = owinner;
      await STUFF(g.P_LEXV, g.AGAIN_LEXV);
      g.P_LEN = getb(g.P_LEXV, P_LEXWORDS);
      ptr = get(g.OOPS_TABLE, O_START);
      await INBUF_STUFF(g.P_INBUF, g.OOPS_INBUF);
    } else {
      put(g.OOPS_TABLE, O_END, false);
      tell("[There was no word to replace!]\n");
      return false;
    }
  } else {
    put(g.OOPS_TABLE, O_END, false);
  }
  if (eq(get(g.P_LEXV, ptr), W.AGAIN, W.G)) {
    if (g.P_OFLAG) {
      (await CANT_USE_THAT_WAY("AGAIN"));
      return false;
    } else if (!g.P_WON) {
      tell("[That would just repeat a mistake!]\n");
      return false;
    } else if (!(owinner == PROTAGONIST) && !(await VISIBLE$(owinner))) {
      tell("[", S(g.YOU_CANT), "see ", D(owinner), " any more.]\n");
      return false;
    } else if (g.P_LEN > 1) {
      if (eq(get(g.P_LEXV, ptr + P_LEXELEN), W.PERIOD, W.COMMA, W.THEN) || eq(get(g.P_LEXV, ptr + P_LEXELEN), W.AND)) {
        ptr = ptr + (2 * P_LEXELEN);
        putb(g.P_LEXV, P_LEXWORDS, getb(g.P_LEXV, P_LEXWORDS) - 2);
      } else {
        await RECOGNIZE();
        return false;
      }
    } else {
      ptr = ptr + P_LEXELEN;
      putb(g.P_LEXV, P_LEXWORDS, getb(g.P_LEXV, P_LEXWORDS) - 1);
    }
    if (getb(g.P_LEXV, P_LEXWORDS) > 0) {
      await STUFF(g.RESERVE_LEXV, g.P_LEXV);
      await INBUF_STUFF(g.RESERVE_INBUF, g.P_INBUF);
      g.RESERVE_PTR = ptr;
    } else {
      g.RESERVE_PTR = false;
    }
    g.WINNER = owinner;
    g.P_MERGED = omerged;
    await INBUF_STUFF(g.P_INBUF, g.OOPS_INBUF);
    await STUFF(g.P_LEXV, g.AGAIN_LEXV);
    cnt = -1;
    dir = g.AGAIN_DIR;
    loop4: for (;;) {
      if (++cnt > P_ITBLLEN) {
        break loop4;
      } else {
        put(g.P_ITBL, cnt, get(g.P_OTBL, cnt));
      }
    }
  } else {
    await STUFF(g.AGAIN_LEXV, g.P_LEXV);
    await INBUF_STUFF(g.OOPS_INBUF, g.P_INBUF);
    put(g.OOPS_TABLE, O_START, ptr);
    put(g.OOPS_TABLE, O_LENGTH, 4 * g.P_LEN);
    len = 2 * (ptr + (P_LEXELEN * getb(g.P_LEXV, P_LEXWORDS)));
    put(g.OOPS_TABLE, O_END, getb(g.P_LEXV, len - 1) + getb(g.P_LEXV, len - 2));
    g.RESERVE_PTR = false;
    len = g.P_LEN;
    g.P_NCN = 0;
    g.P_GETFLAGS = 0;
    loop5: for (;;) {
      if ((g.P_LEN = g.P_LEN - 1) < 0) {
        g.QUOTE_FLAG = false;
        break loop5;
      } else if ((wrd = get(g.P_LEXV, ptr)) || (wrd = await NUMBER$(ptr))) {
        nw = await NEXT_WORD(ptr);
        if ((wrd == W.TO) && (verb == ACT.TELL || verb == ACT.ASK) && (await WT$(nw, PS$VERB, P1$VERB))) {
          put(g.P_ITBL, P_VERB, ACT.TELL);
          wrd = W.QUOTE;
        } else if ((wrd == W.THEN) && (g.P_LEN > 0) && !verb && !g.QUOTE_FLAG) {
          put(g.P_ITBL, P_VERB, ACT.TELL);
          put(g.P_ITBL, P_VERBN, 0);
          wrd = W.QUOTE;
        } else if ((wrd == W.PERIOD) && (lw == W.ST)) {
          g.P_NCN = g.P_NCN - 1;
          await CHANGE_LEXV(ptr, lw, true);
          wrd = lw;
          lw = 0;
        }
        if ((wrd == W.THEN || wrd == W.PERIOD) || (wrd == W.QUOTE)) {
          if (wrd == W.QUOTE) {
            if (g.QUOTE_FLAG) {
              g.QUOTE_FLAG = false;
            } else {
              g.QUOTE_FLAG = true;
            }
          }
          (g.P_LEN == 0) || (g.P_CONT = ptr + P_LEXELEN);
          putb(g.P_LEXV, P_LEXWORDS, g.P_LEN);
          break loop5;
        } else if ((val = await WT$(wrd, PS$DIRECTION, P1$DIRECTION)) && (verb == false || verb == ACT.WALK || verb == ACT.GO) && ((len == 1) || ((len == 2) && (verb == ACT.WALK || verb == ACT.GO)) || ((nw == W.THEN || nw == W.PERIOD || nw == W.QUOTE) && !(len < 2)) || (g.QUOTE_FLAG && (len == 2) && (nw == W.QUOTE)) || ((len > 2) && (nw == W.COMMA || nw == W.AND)))) {
          dir = val;
          if (nw == W.COMMA || nw == W.AND) {
            await CHANGE_LEXV(ptr + P_LEXELEN, W.THEN);
          }
          if (!(len > 2)) {
            g.QUOTE_FLAG = false;
            break loop5;
          }
        } else if ((val = await WT$(wrd, PS$VERB, P1$VERB)) && !verb) {
          g.P_PRSA_WORD = wrd;
          verb = val;
          put(g.P_ITBL, P_VERB, val);
          put(g.P_ITBL, P_VERBN, g.P_VTBL);
          put(g.P_VTBL, 0, wrd);
          putb(g.P_VTBL, 2, getb(g.P_LEXV, cnt = (ptr * 2) + 2));
          putb(g.P_VTBL, 3, getb(g.P_LEXV, cnt + 1));
        } else if ((val = await WT$(wrd, PS$PREPOSITION, 0)) || (wrd == W.ALL || wrd == W.ONE || wrd == W.BOTH) || (wrd == W.EVERYT) || (await WT$(wrd, PS$ADJECTIVE)) || (await WT$(wrd, PS$OBJECT))) {
          if ((g.P_LEN > 0) && (nw == W.OF) && (val == 0) && !(wrd == W.ALL || wrd == W.ONE || wrd == W.A) && !(wrd == W.BOTH || wrd == W.EVERYT)) {
          } else if (!(val == 0) && ((g.P_LEN == 0) || (nw == W.THEN || nw == W.PERIOD))) {
            g.P_END_ON_PREP = true;
            if (g.P_NCN < 2) {
              put(g.P_ITBL, P_PREP1, val);
              put(g.P_ITBL, P_PREP1N, wrd);
            }
          } else if (g.P_NCN == 2) {
            tell("[There were too many nouns in that sentence.]\n");
            return false;
          } else {
            g.P_NCN = g.P_NCN + 1;
            $1 = ptr = await CLAUSE(ptr, val, wrd);
            if (!$1) {
              return false;
            }
            if (ptr < 0) {
              g.QUOTE_FLAG = false;
              break loop5;
            }
          }
        } else if (await WT$(wrd, PS$BUZZ_WORD)) {
        } else if ((verb == ACT.TELL) && (await WT$(wrd, PS$VERB, P1$VERB)) && (g.WINNER == PROTAGONIST)) {
          (await SEE_MANUAL("talk to characters."));
          return false;
        } else {
          await CANT_USE(ptr);
          return false;
        }
      } else {
        await UNKNOWN_WORD(ptr);
        return false;
      }
      lw = wrd;
      ptr = ptr + P_LEXELEN;
    }
  }
  put(g.OOPS_TABLE, O_PTR, false);
  if (dir) {
    g.PRSA = V.WALK;
    g.P_PRSA_WORD = false;
    g.PRSO = dir;
    g.P_OFLAG = false;
    g.P_WALK_DIR = dir;
    g.AGAIN_DIR = dir;
    return true;
  }
  g.P_WALK_DIR = false;
  g.AGAIN_DIR = false;
  if (g.P_OFLAG) {
    await ORPHAN_MERGE();
  }
  if ((await SYNTAX_CHECK()) && (await SNARF_OBJECTS()) && (await MANY_CHECK()) && (await TAKE_CHECK())) {
    return true;
  } else {
    return false;
  }
}

async function CHANGE_LEXV(ptr, wrd, ptrs$ = false) {
  let x = 0, y = 0, z = 0;
  if (ptrs$) {
    x = 2 + (2 * (ptr - P_LEXELEN));
    y = getb(g.P_LEXV, x);
    z = 2 + (2 * ptr);
    putb(g.P_LEXV, z, y);
    putb(g.AGAIN_LEXV, z, y);
    y = getb(g.P_LEXV, 1 + x);
    z = 3 + (2 * ptr);
    putb(g.P_LEXV, z, y);
    putb(g.AGAIN_LEXV, z, y);
  }
  put(g.P_LEXV, ptr, wrd);
  return put(g.AGAIN_LEXV, ptr, wrd);
}

async function STUFF(dest, src, max = 29) {
  let ptr = P_LEXSTART, ctr = 1, bptr = 0;
  putb(dest, 0, getb(src, 0));
  putb(dest, 1, getb(src, 1));
  for (;;) {
    put(dest, ptr, get(src, ptr));
    bptr = (ptr * 2) + 2;
    putb(dest, bptr, getb(src, bptr));
    bptr = (ptr * 2) + 3;
    putb(dest, bptr, getb(src, bptr));
    ptr = ptr + P_LEXELEN;
    if (++ctr > max) {
      return true;
    }
  }
}

async function INBUF_STUFF(dest, src) {
  let cnt = (-1);
  for (;;) {
    if (++cnt > P_INBUF_LENGTH) {
      return true;
    } else {
      putb(dest, cnt, getb(src, cnt));
    }
  }
}

async function INBUF_ADD(len, beg, slot) {
  let dbeg = 0, ctr = 0, tmp = 0;
  if (tmp = get(g.OOPS_TABLE, O_END)) {
    dbeg = tmp;
  } else {
    dbeg = getb(g.AGAIN_LEXV, tmp = get(g.OOPS_TABLE, O_LENGTH)) + getb(g.AGAIN_LEXV, tmp + 1);
  }
  put(g.OOPS_TABLE, O_END, dbeg + len);
  loop1: for (;;) {
    putb(g.OOPS_INBUF, dbeg + ctr, getb(g.P_INBUF, beg + ctr));
    ctr = ctr + 1;
    if (ctr == len) {
      break loop1;
    }
  }
  putb(g.AGAIN_LEXV, slot, dbeg);
  return putb(g.AGAIN_LEXV, slot - 1, len);
}

async function WT$(ptr, bit, b1 = 5) {
  let offs = P_P1OFF, typ = 0;
  if (btst(typ = getb(ptr, P_PSOFF), bit)) {
    if (b1 > 4) {
      return true;
    } else if (bit == PS$OBJECT) {
      return 1;
    } else {
      typ = typ & P_P1BITS;
      if (!(typ == b1)) {
        offs = offs + 1;
      }
      return getb(ptr, offs);
    }
  } else {
    return false;
  }
}

async function NEXT_WORD(ptr) {
  let nw = 0;
  if (!(g.P_LEN == 0)) {
    if (nw = get(g.P_LEXV, ptr + P_LEXELEN)) {
      return nw;
    } else {
      return await NUMBER$(ptr + P_LEXELEN);
    }
  } else {
    return false;
  }
}

async function CLAUSE(ptr, val, wrd) {
  let off = 0, num = 0, andflg = false, first$$ = true, nw = 0, lw = 0;
  off = (g.P_NCN - 1) * 2;
  if (!(val == 0)) {
    put(g.P_ITBL, num = P_PREP1 + off, val);
    put(g.P_ITBL, num + 1, wrd);
    ptr = ptr + P_LEXELEN;
  } else {
    g.P_LEN = g.P_LEN + 1;
  }
  if (g.P_LEN == 0) {
    g.P_NCN = g.P_NCN - 1;
    return -1;
  }
  put(g.P_ITBL, num = P_NC1 + off, g.P_LEXV + (ptr * 2));
  for (;;) {
    if ((g.P_LEN = g.P_LEN - 1) < 0) {
      put(g.P_ITBL, num + 1, g.P_LEXV + (ptr * 2));
      return -1;
    }
    wrd = get(g.P_LEXV, ptr);
    if (wrd || (wrd = await NUMBER$(ptr))) {
      nw = await NEXT_WORD(ptr);
      if (first$$ && ((wrd == W.THE || wrd == W.A || wrd == W.AN) || (val && (await WT$(wrd, PS$PREPOSITION)) && !(await WT$(wrd, PS$ADJECTIVE))))) {
        put(g.P_ITBL, num, get(g.P_ITBL, num) + 4);
      } else if ((wrd == W.PERIOD) && (lw == W.ST)) {
        lw = 0;
      } else if (wrd == W.AND || wrd == W.COMMA) {
        andflg = true;
      } else if ((wrd == W.ALL || wrd == W.ONE || wrd == W.BOTH) || (wrd == W.EVERYT)) {
        if (nw == W.OF) {
          g.P_LEN = g.P_LEN - 1;
          ptr = ptr + P_LEXELEN;
        }
      } else if ((wrd == W.THEN || wrd == W.PERIOD) || ((await WT$(wrd, PS$PREPOSITION)) && get(g.P_ITBL, P_VERB) && !first$$)) {
        g.P_LEN = g.P_LEN + 1;
        put(g.P_ITBL, num + 1, g.P_LEXV + (ptr * 2));
        return ptr - P_LEXELEN;
      } else if (andflg && eq(get(g.P_ITBL, P_VERB), 0)) {
        ptr = ptr - 4;
        await CHANGE_LEXV(ptr + 2, W.THEN);
        g.P_LEN = g.P_LEN + 2;
      } else if (await WT$(wrd, PS$OBJECT)) {
        if ((g.P_LEN > 0) && (nw == W.OF) && !(wrd == W.ALL || wrd == W.EVERYT || wrd == W.ONE)) {
        } else if ((await WT$(wrd, PS$ADJECTIVE)) && !!nw && ((await WT$(nw, PS$OBJECT)) || (await WT$(nw, PS$ADJECTIVE)))) {
        } else if (!andflg && !(nw == W.BUT || nw == W.EXCEPT) && !(nw == W.AND || nw == W.COMMA)) {
          put(g.P_ITBL, num + 1, g.P_LEXV + ((ptr + 2) * 2));
          return ptr;
        } else {
          andflg = false;
        }
      } else if ((await WT$(wrd, PS$ADJECTIVE)) || (await WT$(wrd, PS$BUZZ_WORD))) {
      } else if (await WT$(wrd, PS$PREPOSITION)) {
      } else {
        await CANT_USE(ptr);
        return false;
      }
    } else {
      await UNKNOWN_WORD(ptr);
      return false;
    }
    lw = wrd;
    first$$ = false;
    ptr = ptr + P_LEXELEN;
  }
}

async function NUMBER$(ptr) {
  let cnt = 0, bptr = 0, chr = 0, sum = 0, cctr = 0, tmp = 0, xptr = 0;
  cnt = getb(g.P_LEXV + (ptr * 2), 2);
  bptr = getb(g.P_LEXV + (ptr * 2), 3);
  loop1: for (;;) {
    if (sum > 10000) {
      return false;
    } else if ((cnt = cnt - 1) < 0) {
      break loop1;
    } else {
      chr = getb(g.P_INBUF, bptr);
      if ((chr < 58) && (chr > 47)) {
        sum = (sum * 10) + (chr - 48);
      } else if (!(chr == 35)) {
        return false;
      }
      bptr = bptr + 1;
    }
  }
  await CHANGE_LEXV(ptr, W.NUMBER);
  if (eq(get(g.P_LEXV, ptr + P_LEXELEN), W.COMMA) && (g.P_LEN > 1)) {
    xptr = ptr + (P_LEXELEN * 2);
    if (tmp = await AFTER_COMMA_CHECK(xptr)) {
      cctr = getb(g.P_LEXV, (ptr * 2) + 2);
      cctr = cctr + getb(g.P_LEXV, (xptr * 2) + 2);
      cctr = cctr + 1;
      putb(g.P_LEXV, (ptr * 2) + 2, cctr);
      if (tmp == 1000) {
        tmp = 0;
      }
      sum = (1000 * sum) + tmp;
      cctr = g.P_LEN - 2;
      loop2: for (;;) {
        if (--cctr < 0) {
          break loop2;
        } else {
          ptr = ptr + P_LEXELEN;
          xptr = ptr + (2 * P_LEXELEN);
          await CHANGE_LEXV(ptr, get(g.P_LEXV, xptr));
          putb(g.P_LEXV, (ptr * 2) + 2, getb(g.P_LEXV, (xptr * 2) + 2));
          putb(g.P_LEXV, (ptr * 2) + 3, getb(g.P_LEXV, (xptr * 2) + 3));
        }
      }
      g.P_LEN = g.P_LEN - 2;
      putb(g.P_LEXV, P_LEXWORDS, getb(g.P_LEXV, P_LEXWORDS) - 2);
    }
  }
  if (sum > 10000) {
    return false;
  }
  g.P_NUMBER = sum;
  return W.NUMBER;
}

async function AFTER_COMMA_CHECK(ptr) {
  let cnt = 0, bptr = 0, cctr = 0, chr = 0, sum = 0;
  cnt = getb(g.P_LEXV + (ptr * 2), 2);
  bptr = getb(g.P_LEXV + (ptr * 2), 3);
  loop1: for (;;) {
    if ((cnt = cnt - 1) < 0) {
      break loop1;
    } else {
      chr = getb(g.P_INBUF, bptr);
      cctr = cctr + 1;
      if (cctr > 3) {
        break loop1;
      } else if ((chr < 58) && (chr > 47)) {
        sum = (sum * 10) + (chr - 48);
      } else {
        return false;
      }
      bptr = bptr + 1;
    }
  }
  if (!(cctr == 3)) {
    return false;
  } else if (sum == 0) {
    return 1000;
  } else {
    return sum;
  }
}

async function ORPHAN_MERGE() {
  let cnt = (-1), temp = 0, verb = 0, beg = 0, end = 0, adj = false, wrd = 0;
  g.P_OFLAG = false;
  if (eq(await WT$(wrd = get(get(g.P_ITBL, P_VERBN), 0), PS$VERB, P1$VERB), get(g.P_OTBL, P_VERB)) || (await WT$(wrd, PS$ADJECTIVE))) {
    adj = true;
  } else if ((await WT$(wrd, PS$OBJECT, P1$OBJECT)) && (g.P_NCN == 0)) {
    put(g.P_ITBL, P_VERB, 0);
    put(g.P_ITBL, P_VERBN, 0);
    put(g.P_ITBL, P_NC1, g.P_LEXV + 2);
    put(g.P_ITBL, P_NC1L, g.P_LEXV + 6);
    g.P_NCN = 1;
  }
  if (!((verb = get(g.P_ITBL, P_VERB)) == 0) && !adj && !(verb == get(g.P_OTBL, P_VERB))) {
    return false;
  } else if (g.P_NCN == 2) {
    return false;
  } else if (eq(get(g.P_OTBL, P_NC1), 1)) {
    if (eq(temp = get(g.P_ITBL, P_PREP1), get(g.P_OTBL, P_PREP1)) || (temp == 0)) {
      if (adj) {
        put(g.P_OTBL, P_NC1, g.P_LEXV + 2);
        if (get(g.P_ITBL, P_NC1L) == 0) {
          put(g.P_ITBL, P_NC1L, g.P_LEXV + 6);
        }
        if (g.P_NCN == 0) {
          g.P_NCN = 1;
        }
      } else {
        put(g.P_OTBL, P_NC1, get(g.P_ITBL, P_NC1));
      }
      put(g.P_OTBL, P_NC1L, get(g.P_ITBL, P_NC1L));
    } else {
      return false;
    }
  } else if (eq(get(g.P_OTBL, P_NC2), 1)) {
    if (eq(temp = get(g.P_ITBL, P_PREP1), get(g.P_OTBL, P_PREP2)) || (temp == 0)) {
      if (adj) {
        put(g.P_ITBL, P_NC1, g.P_LEXV + 2);
        if (get(g.P_ITBL, P_NC1L) == 0) {
          put(g.P_ITBL, P_NC1L, g.P_LEXV + 6);
        }
      }
      put(g.P_OTBL, P_NC2, get(g.P_ITBL, P_NC1));
      put(g.P_OTBL, P_NC2L, get(g.P_ITBL, P_NC1L));
      g.P_NCN = 2;
    } else {
      return false;
    }
  } else if (g.P_ACLAUSE) {
    if (!(g.P_NCN == 1) && !adj) {
      g.P_ACLAUSE = false;
      return false;
    } else {
      beg = get(g.P_ITBL, P_NC1);
      if (adj) {
        beg = g.P_LEXV + 2;
        adj = false;
      }
      end = get(g.P_ITBL, P_NC1L);
      loop1: for (;;) {
        wrd = get(beg, 0);
        if (beg == end) {
          if (adj) {
            await CLAUSE_WIN(adj);
            break loop1;
          } else {
            g.P_ACLAUSE = false;
            return false;
          }
        } else if ((wrd == W.ALL || wrd == W.EVERYT || wrd == W.ONE) || (btst(getb(wrd, P_PSOFF), PS$ADJECTIVE) && (await ADJ_CHECK(wrd, adj, adj)))) {
          adj = wrd;
        } else if (wrd == W.ONE) {
          await CLAUSE_WIN(adj);
          break loop1;
        } else if (btst(getb(wrd, P_PSOFF), PS$OBJECT)) {
          if (wrd == g.P_ANAM) {
            await CLAUSE_WIN(adj);
          } else {
            await CLAUSE_WIN();
          }
          break loop1;
        }
        beg = beg + P_WORDLEN;
        if (end == 0) {
          end = beg;
          g.P_NCN = 1;
          put(g.P_ITBL, P_NC1, beg - 4);
          put(g.P_ITBL, P_NC1L, beg);
        }
      }
    }
  }
  put(g.P_VTBL, 0, get(g.P_OVTBL, 0));
  putb(g.P_VTBL, 2, getb(g.P_OVTBL, 2));
  putb(g.P_VTBL, 3, getb(g.P_OVTBL, 3));
  put(g.P_OTBL, P_VERBN, g.P_VTBL);
  putb(g.P_VTBL, 2, 0);
  for (;;) {
    if ((cnt = cnt + 1) > P_ITBLLEN) {
      g.P_MERGED = true;
      return true;
    } else {
      put(g.P_ITBL, cnt, get(g.P_OTBL, cnt));
    }
  }
  return true;
}

async function CLAUSE_WIN(adj = false) {
  if (adj) {
    put(g.P_ITBL, P_VERB, get(g.P_OTBL, P_VERB));
  } else {
    adj = true;
  }
  put(g.P_CCTBL, CC_SBPTR, g.P_ACLAUSE);
  put(g.P_CCTBL, CC_SEPTR, g.P_ACLAUSE + 1);
  if (g.P_ACLAUSE == P_NC1) {
    put(g.P_CCTBL, CC_OCLAUSE, g.P_OCL1);
  } else {
    put(g.P_CCTBL, CC_OCLAUSE, g.P_OCL2);
  }
  await CLAUSE_COPY(g.P_OTBL, g.P_OTBL, adj);
  !(eq(get(g.P_OTBL, P_NC2), 0)) && (g.P_NCN = 2, true);
  g.P_ACLAUSE = false;
  return true;
}

async function WORD_PRINT(cnt, buf) {
  for (;;) {
    if (--cnt < 0) {
      return true;
    } else {
      printC(getb(g.P_INBUF, buf));
      buf = buf + 1;
    }
  }
}

async function UNKNOWN_WORD(ptr) {
  let buf = 0;
  put(g.OOPS_TABLE, O_PTR, ptr);
  tell("[I don't know the word \"");
  await WORD_PRINT(getb(g.P_LEXV + (buf = ptr * 2), 2), getb(g.P_LEXV + buf, 3));
  tell(".\"]\n");
  g.QUOTE_FLAG = false;
  return g.P_OFLAG = false;
}

async function CANT_USE(ptr, for_each_other = false) {
  let buf = 0;
  tell("[You used the word \"");
  if (for_each_other) {
  } else {
    await WORD_PRINT(getb(g.P_LEXV + (buf = ptr * 2), 2), getb(g.P_LEXV + buf, 3));
  }
  tell("\" in a way that I don't understand.]\n");
  return await STOP();
}

async function SYNTAX_CHECK() {
  let syn = 0, len = 0, num = 0, obj = 0, drive1 = false, drive2 = false, prep = 0, verb = 0;
  if ((verb = get(g.P_ITBL, P_VERB)) == 0) {
    tell(S(g.NO_VERB));
    return false;
  }
  syn = get(g.VERBS, 255 - verb);
  len = getb(syn, 0);
  syn = syn + 1;
  loop1: for (;;) {
    num = getb(syn, P_SBITS) & P_SONUMS;
    if (g.P_NCN > num) {
    } else if (!(num < 1) && (g.P_NCN == 0) && (((prep = get(g.P_ITBL, P_PREP1)) == 0) || (prep == getb(syn, P_SPREP1)))) {
      drive1 = syn;
    } else if (eq(getb(syn, P_SPREP1), get(g.P_ITBL, P_PREP1))) {
      if ((num == 2) && (g.P_NCN == 1)) {
        drive2 = syn;
      } else if (eq(getb(syn, P_SPREP2), get(g.P_ITBL, P_PREP2))) {
        await SYNTAX_FOUND(syn);
        return true;
      }
    }
    if (--len < 1) {
      if (drive1 || drive2) {
        break loop1;
      } else {
        await RECOGNIZE();
        return false;
      }
    } else {
      syn = syn + P_SYNLEN;
    }
  }
  if (drive1 && (obj = await GWIM(getb(drive1, P_SFWIM1), getb(drive1, P_SLOC1), getb(drive1, P_SPREP1)))) {
    putb(g.P_PRSO, g.P_MATCHLEN, 1);
    putb(g.P_PRSO, 1, obj);
    return await SYNTAX_FOUND(drive1);
  } else if (drive2 && (obj = await GWIM(getb(drive2, P_SFWIM2), getb(drive2, P_SLOC2), getb(drive2, P_SPREP2)))) {
    putb(g.P_PRSI, g.P_MATCHLEN, 1);
    putb(g.P_PRSI, 1, obj);
    return await SYNTAX_FOUND(drive2);
  } else {
    if (g.WINNER == PROTAGONIST) {
      await ORPHAN(drive1, drive2);
      tell("[Wh");
    } else {
      tell("[Your command was not complete. Next time, type wh");
    }
    if (verb == ACT.WALK || verb == ACT.GO) {
      tell("ere");
    } else if ((drive1 && eq(getb(drive1, P_SFWIM1), ACTORBIT)) || (drive2 && eq(getb(drive2, P_SFWIM2), ACTORBIT))) {
      tell("om");
    } else {
      tell("at");
    }
    if (g.WINNER == PROTAGONIST) {
      tell(S(DO_YOU_WANT));
    } else {
      tell(" you want");
      await TPRINT(g.WINNER);
      tell(" to ");
    }
    await VERB_PRINT();
    g.P_OFLAG = false;
    if (drive2) {
      prep = g.P_MERGED;
      g.P_MERGED = false;
      await CLAUSE_PRINT(P_NC1, P_NC1L);
      g.P_MERGED = prep;
    }
    await PREP_PRINT(drive1 ? getb(drive1, P_SPREP1) : getb(drive2, P_SPREP2));
    if (g.WINNER == PROTAGONIST) {
      g.P_OFLAG = true;
      tell("?]\n");
    } else {
      g.P_OFLAG = false;
      tell(".]\n");
    }
    return false;
  }
}

async function VERB_PRINT() {
  let tmp = 0;
  tmp = get(g.P_ITBL, P_VERBN);
  if (tmp == 0) {
    tell("tell");
    return true;
  } else if (tmp == W.ZZMGCK) {
    tell("answer");
    return true;
  } else if (getb(tmp, 2) == 0) {
    return printB(get(tmp, 0));
  } else {
    await WORD_PRINT(getb(tmp, 2), getb(tmp, 3));
    return putb(tmp, 2, 0);
  }
}

async function CANT_ORPHAN() {
  tell("\"I don't understand! What are you referring to?\"\n");
  return false;
}

async function ORPHAN(d1, d2) {
  let cnt = (-1);
  if (!g.P_MERGED) {
    put(g.P_OCL1, g.P_MATCHLEN, 0);
    put(g.P_OCL2, g.P_MATCHLEN, 0);
  }
  put(g.P_OVTBL, 0, get(g.P_VTBL, 0));
  putb(g.P_OVTBL, 2, getb(g.P_VTBL, 2));
  putb(g.P_OVTBL, 3, getb(g.P_VTBL, 3));
  loop1: for (;;) {
    if (++cnt > P_ITBLLEN) {
      break loop1;
    } else {
      put(g.P_OTBL, cnt, get(g.P_ITBL, cnt));
    }
  }
  if (g.P_NCN == 2) {
    put(g.P_CCTBL, CC_SBPTR, P_NC2);
    put(g.P_CCTBL, CC_SEPTR, P_NC2L);
    put(g.P_CCTBL, CC_OCLAUSE, g.P_OCL2);
    await CLAUSE_COPY(g.P_ITBL, g.P_OTBL);
  }
  if (!(g.P_NCN < 1)) {
    put(g.P_CCTBL, CC_SBPTR, P_NC1);
    put(g.P_CCTBL, CC_SEPTR, P_NC1L);
    put(g.P_CCTBL, CC_OCLAUSE, g.P_OCL1);
    await CLAUSE_COPY(g.P_ITBL, g.P_OTBL);
  }
  if (d1) {
    put(g.P_OTBL, P_PREP1, getb(d1, P_SPREP1));
    return put(g.P_OTBL, P_NC1, 1);
  } else if (d2) {
    put(g.P_OTBL, P_PREP2, getb(d2, P_SPREP2));
    return put(g.P_OTBL, P_NC2, 1);
  } else {
    return false;
  }
}

async function CLAUSE_PRINT(bptr, eptr, the$ = true) {
  return await BUFFER_PRINT(get(g.P_ITBL, bptr), get(g.P_ITBL, eptr), the$);
}

async function BUFFER_PRINT(beg, end, cp) {
  let nosp = false, wrd = 0, first$$ = true, pn = false;
  for (;;) {
    if (beg == end) {
      return true;
    } else {
      if (nosp) {
        nosp = false;
      } else {
        tell(" ");
      }
      if (eq(wrd = get(beg, 0), W.PERIOD) || (first$$ && (wrd == W.OF))) {
        nosp = true;
      } else if (wrd == W.ME || wrd == W.MYSELF) {
        printD(ME);
        pn = true;
      } else if (await NAME$(wrd)) {
        await CAPITALIZE(beg);
        pn = true;
      } else {
        if (first$$ && !pn && cp && !(wrd == W.MY || wrd == W.HER)) {
          tell("the ");
        }
        if (g.P_OFLAG || g.P_MERGED) {
          printB(wrd);
        } else if ((wrd == W.IT || wrd == W.THEM) && (await ACCESSIBLE$(g.P_IT_OBJECT))) {
          tell(D(g.P_IT_OBJECT));
        } else if ((wrd == W.HIM || wrd == W.HIMSELF) && (await ACCESSIBLE$(g.P_HIM_OBJECT))) {
          tell(D(g.P_HIM_OBJECT));
        } else if ((wrd == W.HER || wrd == W.HERSELF) && (await ACCESSIBLE$(g.P_HER_OBJECT))) {
          tell(D(g.P_HER_OBJECT));
        } else {
          await WORD_PRINT(getb(beg, 2), getb(beg, 3));
        }
        first$$ = false;
      }
    }
    beg = beg + P_WORDLEN;
  }
}

async function NAME$(wrd) {
  if ((wrd == W.DAD || wrd == W.PAPA || wrd == W.FATHER || wrd == W.DIMSFORD) || (wrd == W.CRULLEY || wrd == W.LUCY || wrd == W.LAFOND || wrd == W.GOVERNOR) || (wrd == W.JAMISON || wrd == W.COOKIE || wrd == W.QUICK || wrd == W.RODNEY) || (wrd == W.LOUISE || wrd == W.DAVIS || wrd == W.SINISTRA || wrd == W.LATIN) || (wrd == W.NICK || wrd == W.NICHOLAS || wrd == W.FALCON || wrd == W.HELENA) || (wrd == W.JEAN || wrd == W.ANDY || wrd == W.ANDREW || wrd == W.ST) || (wrd == W.ERNEST || wrd == W.RYALL || wrd == W.RODNEY)) {
    return true;
  } else {
    return false;
  }
}

async function ADJNAME$(adj) {
  if ((adj == A.NICK || adj == A.NICHOLAS || adj == A.FALCON || adj == A.HELENA) || (adj == A.JEAN || adj == A.ANDY || adj == A.ANDREW || adj == A.ST) || (adj == A.ERNEST || adj == A.RYALL || adj == A.RODNEY)) {
    return true;
  } else {
    return false;
  }
}

async function CAPITALIZE(ptr) {
  if (g.P_OFLAG || g.P_MERGED) {
    return printB(get(ptr, 0));
  } else {
    printC(getb(g.P_INBUF, getb(ptr, 3)) - 32);
    return await WORD_PRINT(getb(ptr, 2) - 1, getb(ptr, 3) + 1);
  }
}

async function PREP_PRINT(prep) {
  let wrd = 0;
  if (!(prep == 0)) {
    tell(" ");
    if (prep == PR.THROUGH) {
      tell("through");
      return true;
    } else {
      wrd = await PREP_FIND(prep);
      return printB(wrd);
    }
  } else {
    return false;
  }
}

async function CLAUSE_COPY(src, dest, insrt = false) {
  let ocl = 0, beg = 0, end = 0, bb = 0, ee = 0, obeg = 0, cnt = 0, b = 0, e = 0;
  bb = get(g.P_CCTBL, CC_SBPTR);
  ee = get(g.P_CCTBL, CC_SEPTR);
  ocl = get(g.P_CCTBL, CC_OCLAUSE);
  beg = get(src, bb);
  end = get(src, ee);
  obeg = get(ocl, g.P_MATCHLEN);
  loop1: for (;;) {
    if (beg == end) {
      break loop1;
    }
    if (insrt && (g.P_ANAM == get(beg, 0))) {
      if (insrt == true) {
        b = get(g.P_ITBL, P_NC1);
        e = get(g.P_ITBL, P_NC1L);
        loop2: for (;;) {
          if (b == e) {
            break loop2;
          }
          await CLAUSE_ADD(get(b, 0));
          b = b + P_WORDLEN;
        }
      } else if (!(insrt == get(ocl, 1))) {
        await CLAUSE_ADD(insrt);
        await CLAUSE_ADD(get(beg, 0));
      }
    } else {
      await CLAUSE_ADD(get(beg, 0));
    }
    beg = beg + P_WORDLEN;
  }
  if ((src == dest) && (obeg > 0)) {
    cnt = get(ocl, g.P_MATCHLEN) - obeg;
    put(ocl, g.P_MATCHLEN, 0);
    obeg = obeg + 1;
    loop3: for (;;) {
      await CLAUSE_ADD(get(ocl, obeg));
      if ((cnt = cnt - 2) == 0) {
        break loop3;
      }
      obeg = obeg + 2;
    }
    obeg = 0;
  }
  put(dest, bb, ocl + ((obeg * P_LEXELEN) + 2));
  return put(dest, ee, ocl + ((get(ocl, g.P_MATCHLEN) * P_LEXELEN) + 2));
}

async function CLAUSE_ADD(wrd) {
  let ocl = 0, ptr = 0;
  ocl = get(g.P_CCTBL, CC_OCLAUSE);
  ptr = get(ocl, g.P_MATCHLEN) + 2;
  put(ocl, ptr - 1, wrd);
  put(ocl, ptr, 0);
  return put(ocl, g.P_MATCHLEN, ptr);
}

async function PREP_FIND(prep) {
  let cnt = 0, size = 0;
  size = get(g.PREPOSITIONS, 0) * 2;
  for (;;) {
    if (++cnt > size) {
      return false;
    } else if (eq(get(g.PREPOSITIONS, cnt), prep)) {
      return get(g.PREPOSITIONS, cnt - 1);
    }
  }
}

async function SYNTAX_FOUND(syn) {
  g.P_SYNTAX = syn;
  return g.PRSA = getb(syn, P_SACTION);
}

async function GWIM(gbit, lbit, prep) {
  let obj = 0;
  if (gbit == RLANDBIT) {
    return ROOMS;
  }
  g.P_GWIMBIT = gbit;
  g.P_SLOCBITS = lbit;
  putb(g.P_MERGE, g.P_MATCHLEN, 0);
  if (await GET_OBJECT(g.P_MERGE, false)) {
    g.P_GWIMBIT = 0;
    if (eq(getb(g.P_MERGE, g.P_MATCHLEN), 1)) {
      obj = getb(g.P_MERGE, 1);
      tell("[");
      if (!(prep == 0) && !g.P_END_ON_PREP) {
        printB(prep = await PREP_FIND(prep));
        if (prep == W.OUT) {
          tell(" of");
        }
        if (!(hasFlag(obj, NARTICLEBIT))) {
          tell(" the ");
        } else {
          tell(" ");
        }
      }
      tell(D(obj), "]\n");
      return obj;
    } else {
      return false;
    }
  } else {
    g.P_GWIMBIT = 0;
    return false;
  }
}

async function SNARF_OBJECTS() {
  let ptr = 0;
  let $1, $2;
  if (!(eq(ptr = get(g.P_ITBL, P_NC1), 0))) {
    g.P_PHR = 0;
    g.P_SLOCBITS = getb(g.P_SYNTAX, P_SLOC1);
    $1 = await SNARFEM(ptr, get(g.P_ITBL, P_NC1L), g.P_PRSO);
    if (!$1) {
      return false;
    }
    (getb(g.P_BUTS, g.P_MATCHLEN) == 0) || (g.P_PRSO = await BUT_MERGE(g.P_PRSO));
  }
  if (!(eq(ptr = get(g.P_ITBL, P_NC2), 0))) {
    g.P_PHR = 1;
    g.P_SLOCBITS = getb(g.P_SYNTAX, P_SLOC2);
    $2 = await SNARFEM(ptr, get(g.P_ITBL, P_NC2L), g.P_PRSI);
    if (!$2) {
      return false;
    }
    if (!(getb(g.P_BUTS, g.P_MATCHLEN) == 0)) {
      if (eq(getb(g.P_PRSI, g.P_MATCHLEN), 1)) {
        g.P_PRSO = await BUT_MERGE(g.P_PRSO);
      } else {
        g.P_PRSI = await BUT_MERGE(g.P_PRSI);
      }
    }
  }
  return true;
}

async function BUT_MERGE(tbl) {
  let len = 0, butlen = 0, cnt = 1, matches = 0, obj = 0, ntbl = 0;
  len = getb(tbl, g.P_MATCHLEN);
  putb(g.P_MERGE, g.P_MATCHLEN, 0);
  loop1: for (;;) {
    if (--len < 0) {
      break loop1;
    } else if (!(await ZMEMQB(obj = getb(tbl, cnt), g.P_BUTS))) {
      matches = matches + 1;
      putb(g.P_MERGE, matches, obj);
    }
    cnt = cnt + 1;
  }
  putb(g.P_MERGE, g.P_MATCHLEN, matches);
  ntbl = g.P_MERGE;
  g.P_MERGE = tbl;
  return ntbl;
}

async function SNARFEM(ptr, eptr, tbl) {
  let but = false, len = 0, wv = 0, wrd = 0, nw = 0, was_all = false;
  let $1, $2, $3, $4;
  g.P_AND = false;
  if (g.P_GETFLAGS == P_ALL) {
    was_all = true;
  }
  g.P_GETFLAGS = 0;
  putb(g.P_BUTS, g.P_MATCHLEN, 0);
  putb(tbl, g.P_MATCHLEN, 0);
  wrd = get(ptr, 0);
  for (;;) {
    if (ptr == eptr) {
      wv = await GET_OBJECT(but || tbl);
      if (was_all) {
        g.P_GETFLAGS = P_ALL;
      }
      return wv;
    } else {
      if (eptr == (ptr + P_WORDLEN)) {
        nw = 0;
      } else {
        nw = get(ptr, P_LEXELEN);
      }
      if (wrd == W.ALL || wrd == W.BOTH || wrd == W.EVERYT) {
        if (!(await MANY_CHECK(g.P_PHR))) {
          return false;
        }
        g.P_GETFLAGS = P_ALL;
        if (nw == W.OF) {
          ptr = ptr + P_WORDLEN;
        }
      } else if (wrd == W.BUT || wrd == W.EXCEPT) {
        $1 = await GET_OBJECT(but || tbl);
        if (!$1) {
          return false;
        }
        but = g.P_BUTS;
        putb(but, g.P_MATCHLEN, 0);
      } else if (wrd == W.A || wrd == W.ONE) {
        if (!g.P_ADJ) {
          g.P_GETFLAGS = P_ONE;
          if (nw == W.OF) {
            ptr = ptr + P_WORDLEN;
          }
        } else {
          g.P_NAM = g.P_ONEOBJ;
          $2 = await GET_OBJECT(but || tbl);
          if (!$2) {
            return false;
          }
          $3 = nw == 0;
          if ($3) {
            return true;
          }
        }
      } else if ((wrd == W.AND || wrd == W.COMMA) && !(nw == W.AND || nw == W.COMMA)) {
        g.P_AND = true;
        $4 = await GET_OBJECT(but || tbl);
        if (!$4) {
          return false;
        }
      } else if (await WT$(wrd, PS$BUZZ_WORD)) {
      } else if (wrd == W.AND || wrd == W.COMMA) {
      } else if (wrd == W.OF) {
        if (g.P_GETFLAGS == 0) {
          g.P_GETFLAGS = P_INHIBIT;
        }
      } else if ((wv = await WT$(wrd, PS$ADJECTIVE, P1$ADJECTIVE)) && (await ADJ_CHECK(wrd, g.P_ADJ, g.P_ADJN)) && !(nw == W.OF)) {
        g.P_ADJ = wv;
        g.P_ADJN = wrd;
      } else if (await WT$(wrd, PS$OBJECT, P1$OBJECT)) {
        g.P_NAM = wrd;
        g.P_ONEOBJ = wrd;
      }
    }
    if (!(ptr == eptr)) {
      ptr = ptr + P_WORDLEN;
      wrd = nw;
    }
  }
}

async function ADJ_CHECK(wrd, adj, adjn) {
  if (!adj) {
    return true;
  } else {
    return false;
  }
}

async function GET_OBJECT(tbl, vrb = true) {
  let bits = 0, len = 0, xbits = 0, tlen = 0, gcheck = false, olen = 0, obj = 0;
  xbits = g.P_SLOCBITS;
  tlen = getb(tbl, g.P_MATCHLEN);
  if (btst(g.P_GETFLAGS, P_INHIBIT)) {
    return true;
  }
  if (!g.P_NAM && g.P_ADJ) {
    if (await WT$(g.P_ADJN, PS$OBJECT, P1$OBJECT)) {
      g.P_NAM = g.P_ADJN;
      g.P_ADJ = false;
      g.P_ADJN = false;
    } else if (bits = await WT$(g.P_ADJN, PS$DIRECTION, P1$DIRECTION)) {
      g.P_DIRECTION = bits;
    }
  }
  if (!g.P_NAM && !g.P_ADJ && !(g.P_GETFLAGS == P_ALL) && (g.P_GWIMBIT == 0)) {
    if (vrb) {
      tell(S(g.NOUN_MISSING));
    }
    return false;
  }
  if (!(g.P_GETFLAGS == P_ALL) || (g.P_SLOCBITS == 0)) {
    g.P_SLOCBITS = -1;
  }
  g.P_TABLE = tbl;
  loop1: for (;;) {
    if (gcheck) {
      await GLOBAL_CHECK(tbl);
    } else {
      if (g.LIT || isVerb(V.TELL)) {
        clearFlag(PROTAGONIST, TRANSBIT);
        await DO_SL(g.HERE, SOG, SIR);
        setFlag(PROTAGONIST, TRANSBIT);
      } else if (hasFlag(loc(PROTAGONIST), VEHBIT) && (await THIS_IT$(loc(PROTAGONIST)))) {
        await OBJ_FOUND(loc(PROTAGONIST), tbl);
      }
      await DO_SL(PROTAGONIST, SH, SC);
    }
    len = getb(tbl, g.P_MATCHLEN) - tlen;
    if (btst(g.P_GETFLAGS, P_ALL)) {
    } else if (!(g.P_GETFLAGS == P_ALL) && ((len > 1) || ((len == 0) && !(g.P_SLOCBITS == (-1))))) {
      if (g.P_SLOCBITS == (-1)) {
        g.P_SLOCBITS = xbits;
        olen = len;
        putb(tbl, g.P_MATCHLEN, getb(tbl, g.P_MATCHLEN) - len);
        continue loop1;
      } else {
        await PUT_ADJ_NAM();
        if (len == 0) {
          len = olen;
        }
        if (g.P_NAM && (obj = getb(tbl, tlen + 1)) && (obj = await apply(getProp(obj, P.GENERIC)))) {
          if (obj == NOT_HERE_OBJECT) {
            return false;
          }
          putb(tbl, 1, obj);
          putb(tbl, g.P_MATCHLEN, 1);
          g.P_NAM = false;
          g.P_ADJ = false;
          return true;
        } else if (vrb && !(g.WINNER == PROTAGONIST)) {
          await CANT_ORPHAN();
          g.P_NAM = false;
          g.P_ADJ = false;
          return false;
        } else if (vrb && g.P_NAM) {
          await WHICH_PRINT(tlen, len, tbl);
          g.P_ACLAUSE = tbl == g.P_PRSO ? P_NC1 : P_NC2;
          g.P_AADJ = g.P_ADJ;
          g.P_ANAM = g.P_NAM;
          await ORPHAN(false, false);
          g.P_OFLAG = true;
        } else if (vrb) {
          tell(S(g.NOUN_MISSING));
        }
        g.P_NAM = false;
        g.P_ADJ = false;
        return false;
      }
    } else if ((len == 0) && gcheck) {
      await PUT_ADJ_NAM();
      if (vrb) {
        g.P_SLOCBITS = xbits;
        if (g.LIT || (g.PRSA == V.TELL || g.PRSA == V.OPEN) || (g.PRSA == V.WHERE || g.PRSA == V.WHAT)) {
          await OBJ_FOUND(NOT_HERE_OBJECT, tbl);
          g.P_XNAM = g.P_NAM;
          g.P_XADJ = g.P_ADJ;
          g.P_XADJN = g.P_ADJN;
          g.P_NAM = false;
          g.P_ADJ = false;
          g.P_ADJN = false;
          return true;
        } else {
          tell(S(g.TOO_DARK), "\n");
        }
      }
      g.P_NAM = false;
      g.P_ADJ = false;
      return false;
    } else if (len == 0) {
      gcheck = true;
      continue loop1;
    }
    g.P_SLOCBITS = xbits;
    await PUT_ADJ_NAM();
    g.P_NAM = false;
    g.P_ADJ = false;
    return true;
  }
}

async function PUT_ADJ_NAM() {
  if (!(g.P_NAM == W.IT)) {
    put(g.P_NAMW, g.P_PHR, g.P_NAM);
    return put(g.P_ADJW, g.P_PHR, g.P_ADJ);
  } else {
    return false;
  }
}

async function MOBY_FIND(tbl) {
  let obj = 1, len = 0, foo = 0, nam = 0, adj = 0;
  nam = g.P_NAM;
  adj = g.P_ADJ;
  g.P_NAM = g.P_XNAM;
  g.P_ADJ = g.P_XADJ;
  putb(tbl, g.P_MATCHLEN, 0);
  loop1: for (;;) {
    loop2: for (;;) {
      if (foo = await THIS_IT$(obj)) {
        foo = await OBJ_FOUND(obj, tbl);
      }
      if (++obj > LAST_OBJECT) {
        break loop2;
      }
    }
    break loop1;
  }
  if (eq(len = getb(tbl, g.P_MATCHLEN), 1)) {
    g.P_MOBY_FOUND = getb(tbl, 1);
  }
  g.P_NAM = nam;
  g.P_ADJ = adj;
  return len;
}

async function WHICH_PRINT(tlen, len, tbl) {
  let obj = 0, rlen = 0;
  rlen = len;
  tell("[Which");
  if (g.P_OFLAG || g.P_MERGED || g.P_AND) {
    tell(" ");
    printB(g.P_NAM);
  } else if (tbl == g.P_PRSO) {
    await CLAUSE_PRINT(P_NC1, P_NC1L, false);
  } else {
    await CLAUSE_PRINT(P_NC2, P_NC2L, false);
  }
  tell(" dost thou mean, ");
  for (;;) {
    tlen = tlen + 1;
    obj = getb(tbl, tlen);
    if (!(hasFlag(obj, NARTICLEBIT))) {
      tell("the ");
    }
    tell(D(obj));
    if (len == 2) {
      if (!(rlen == 2)) {
        tell(",");
      }
      tell(" or ");
    } else if (len > 2) {
      tell(", ");
    }
    if ((len = len - 1) < 1) {
      tell("?]\n");
      return true;
    }
  }
}

async function GLOBAL_CHECK(tbl) {
  let len = 0, rmg = 0, rmgl = 0, cnt = 0, obj = 0, obits = 0, foo = 0;
  len = getb(tbl, g.P_MATCHLEN);
  obits = g.P_SLOCBITS;
  if (rmg = getPropAddr(g.HERE, P.GLOBAL)) {
    rmgl = propSize(rmg) - 1;
    loop1: for (;;) {
      if (await THIS_IT$(obj = getb(rmg, cnt))) {
        await OBJ_FOUND(obj, tbl);
      }
      if (++cnt > rmgl) {
        break loop1;
      }
    }
  }
  if (eq(getb(tbl, g.P_MATCHLEN), len)) {
    g.P_SLOCBITS = -1;
    g.P_TABLE = tbl;
    await DO_SL(GLOBAL_OBJECTS, 1, 1);
    return g.P_SLOCBITS = obits;
  } else {
    return false;
  }
}

async function DO_SL(obj, bit1, bit2) {
  let bts = 0;
  if (btst(g.P_SLOCBITS, bit1 + bit2)) {
    return await SEARCH_LIST(obj, g.P_TABLE, P_SRCALL);
  } else {
    if (btst(g.P_SLOCBITS, bit1)) {
      return await SEARCH_LIST(obj, g.P_TABLE, P_SRCTOP);
    } else if (btst(g.P_SLOCBITS, bit2)) {
      return await SEARCH_LIST(obj, g.P_TABLE, P_SRCBOT);
    } else {
      return true;
    }
  }
}

async function SEARCH_LIST(obj, tbl, lvl) {
  let fls = 0, nobj = 0;
  if (obj = first(obj)) {
    for (;;) {
      if (!(lvl == P_SRCBOT) && getPropAddr(obj, P.SYNONYM) && (await THIS_IT$(obj))) {
        await OBJ_FOUND(obj, tbl);
      }
      if ((!(lvl == P_SRCTOP) || hasFlag(obj, SEARCHBIT) || hasFlag(obj, SURFACEBIT)) && (nobj = first(obj))) {
        if (hasFlag(obj, OPENBIT) || hasFlag(obj, TRANSBIT) || g.P_MOBY_FLAG) {
          fls = await SEARCH_LIST(obj, tbl, hasFlag(obj, SURFACEBIT) ? P_SRCALL : (hasFlag(obj, SEARCHBIT) ? P_SRCALL : P_SRCTOP));
        }
      }
      if (obj = next(obj)) {
      } else {
        return true;
      }
    }
  } else {
    return false;
  }
}

async function OBJ_FOUND(obj, tbl) {
  let ptr = 0;
  ptr = getb(tbl, g.P_MATCHLEN);
  putb(tbl, ptr + 1, obj);
  return putb(tbl, g.P_MATCHLEN, ptr + 1);
}

async function TAKE_CHECK() {
  return (await ITAKE_CHECK(g.P_PRSO, getb(g.P_SYNTAX, P_SLOC1))) && (await ITAKE_CHECK(g.P_PRSI, getb(g.P_SYNTAX, P_SLOC2)));
}

async function ITAKE_CHECK(tbl, ibits) {
  let ptr = 0, obj = 0, taken = 0;
  if ((ptr = getb(tbl, g.P_MATCHLEN)) && (btst(ibits, SHAVE) || btst(ibits, STAKE))) {
    for (;;) {
      if ((ptr = ptr - 1) < 0) {
        return true;
      } else {
        obj = getb(tbl, ptr + 1);
        if (obj == IT) {
          if (!(await VISIBLE$(g.P_IT_OBJECT))) {
            await REFERRING();
            return false;
          } else {
            obj = g.P_IT_OBJECT;
          }
        } else if (obj == HIM) {
          if (!(await VISIBLE$(g.P_HIM_OBJECT))) {
            await REFERRING(true);
            return false;
          } else {
            obj = g.P_HIM_OBJECT;
          }
        } else if (obj == HER) {
          if (!(await VISIBLE$(g.P_HER_OBJECT))) {
            await REFERRING(true);
            return false;
          } else {
            obj = g.P_HER_OBJECT;
          }
        }
        if (await HELD$(obj)) {
        } else if (obj == HANDS) {
        } else if (isVerb(V.TAKE_WITH) && (obj == MAN)) {
        } else {
          g.PRSO = obj;
          if (hasFlag(obj, TRYTAKEBIT)) {
            taken = true;
          } else if (await UNTOUCHABLE$(obj)) {
            taken = true;
          } else if ((obj == WINE) && ((await HELD$(BLUE_GLASS)) || (await HELD$(GREEN_GLASS)))) {
            taken = false;
          } else if ((g.HERE == ON_LADDER) && (obj == LADDER)) {
            taken = false;
          } else if (!(g.WINNER == PROTAGONIST)) {
            taken = false;
          } else if (btst(ibits, STAKE) && eq(await ITAKE(false), true)) {
            taken = false;
          } else {
            taken = true;
          }
          if (taken && btst(ibits, SHAVE)) {
            if (1 < getb(tbl, g.P_MATCHLEN)) {
              tell(S(g.YNH), " those things!\n");
              return false;
            } else if (obj == NOT_HERE_OBJECT) {
              tell(S(g.YOU_CANT), "see that here!\n");
              return false;
            }
            if (g.WINNER == PROTAGONIST) {
              tell(S(g.YNH));
            } else {
              tell(S(DOESNT_LOOK));
              await TPRINT(g.WINNER);
              tell(" has");
            }
            await THIS_IS_IT(obj);
            await TRPRINT(obj);
            return false;
          } else if (!taken && !(loc(PROTAGONIST) == obj) && (g.WINNER == PROTAGONIST)) {
            tell("[taking");
            await TPRINT(obj);
            tell(" first]\n");
          }
        }
      }
    }
  } else {
    return true;
  }
}

async function MANY_CHECK(phr = 2) {
  let loss = false, tmp = 0;
  if ((phr == 0) && !(btst(getb(g.P_SYNTAX, P_SLOC1), SMANY))) {
    loss = 1;
  } else if ((phr == 1) && !(btst(getb(g.P_SYNTAX, P_SLOC2), SMANY))) {
    loss = 2;
  } else if ((phr == 2) && (getb(g.P_PRSO, g.P_MATCHLEN) > 1) && !(btst(getb(g.P_SYNTAX, P_SLOC1), SMANY))) {
    loss = 1;
  } else if ((phr == 2) && (getb(g.P_PRSI, g.P_MATCHLEN) > 1) && !(btst(getb(g.P_SYNTAX, P_SLOC2), SMANY))) {
    loss = 2;
  }
  if (loss) {
    tell("[", S(g.YOU_CANT), "use multiple ");
    if (loss == 2) {
      tell("in");
    }
    tell("direct objects with \"");
    tmp = get(g.P_ITBL, P_VERBN);
    if (tmp == 0) {
      tell("tell");
    } else if (g.P_OFLAG || g.P_MERGED) {
      printB(get(tmp, 0));
    } else {
      await WORD_PRINT(getb(tmp, 2), getb(tmp, 3));
    }
    tell("\".]\n");
    return false;
  } else {
    return true;
  }
}

async function ZMEMQ(itm, tbl, size = (-1)) {
  let cnt = 1;
  if (!tbl) {
    return false;
  }
  if (!(size < 0)) {
    cnt = 0;
  } else {
    size = get(tbl, 0);
  }
  for (;;) {
    if (itm == get(tbl, cnt)) {
      return true;
    } else if (++cnt > size) {
      return false;
    }
  }
}

async function ZMEMQB(itm, tbl, size = (-1)) {
  let cnt = 1;
  if (!(size < 0)) {
    cnt = 0;
  } else {
    size = getb(tbl, 0);
  }
  for (;;) {
    if (itm == getb(tbl, cnt)) {
      return true;
    } else if (++cnt > size) {
      return false;
    }
  }
}

async function LIT$(rm, rmbit = true) {
  let ohere = 0, lit = false;
  g.P_GWIMBIT = ONBIT;
  ohere = g.HERE;
  g.HERE = rm;
  if (rmbit && hasFlag(rm, ONBIT)) {
    lit = true;
  } else {
    putb(g.P_MERGE, g.P_MATCHLEN, 0);
    g.P_TABLE = g.P_MERGE;
    g.P_SLOCBITS = -1;
    if (ohere == rm) {
      await DO_SL(g.WINNER, 1, 1);
      if (!(g.WINNER == PROTAGONIST) && (loc(PROTAGONIST) == rm)) {
        await DO_SL(PROTAGONIST, 1, 1);
      }
    }
    await DO_SL(rm, 1, 1);
    if (get(g.P_TABLE, g.P_MATCHLEN) > 0) {
      lit = true;
    }
  }
  g.HERE = ohere;
  g.P_GWIMBIT = 0;
  return lit;
}

