async function YES$() {
  restart: for (;;) {
    print(">");
    await read(g.P_INBUF, g.P_LEXV);
    if (await YES_WORD(get(g.P_LEXV, 1))) {
      return true;
    } else if ((await NO_WORD(get(g.P_LEXV, 1))) || eq(get(g.P_LEXV, 1), W.N)) {
      return false;
    } else {
      tell("This is important: please answer YES or NO. ");
      continue restart;
    }
  }
}

async function FINISH() {
  let repeating = false, cnt = 0;
  loop1: for (;;) {
    crlf();
    if (!repeating) {
      repeating = true;
      tell(S(g.INDENT));
      await V_SCORE();
    }
    if (g.SCORE > 24) {
      tell(S(g.INDENT), "Thus you have finished the story of ", S(g.GAME_CAPS), ", earning the title, \"", S(get(g.WINNING_RANKS, g.FINAL_RANK)), ".\"");
      if (g.FINAL_RANK < 4) {
        tell(" There are other, perhaps more satisfying, conclusions.");
      }
      crlf();
    }
    tell(S(g.INDENT), "You may start over, restore a saved position, or end this session of the game. (Type RESTART, RESTORE, or QUIT):\n>");
    putb(g.P_LEXV, 0, 10);
    await read(g.P_INBUF, g.P_LEXV);
    putb(g.P_LEXV, 0, 60);
    cnt = cnt + 1;
    if (eq(get(g.P_LEXV, 1), W.RESTAR)) {
      await restart();
      tell(S(g.FAILED));
      continue loop1;
    } else if (eq(get(g.P_LEXV, 1), W.RESTOR) && !(await restore())) {
      tell(S(g.FAILED));
      continue loop1;
    } else if (eq(get(g.P_LEXV, 1), W.QUIT, W.Q) || (cnt > 10)) {
      await quit();
    }
    continue loop1;
  }
}

