async function REMOVE_CLOTHES(called_by_get_undressed = false) {
  let x = 0, n_ = 0;
  if (called_by_get_undressed) {
    if (await LAF_DOFF_CHECK()) {
      return true;
    } else {
      tell("You");
      if (!(hasFlag(CHEMISE, EVERYBIT)) && !(hasFlag(PANTS, WORNBIT)) && !(hasFlag(SHIRT, WORNBIT))) {
        tell("'re already stripped!\n");
        return true;
      } else {
        tell(" strip down to your chemise", S(g.PCR));
      }
    }
  }
  x = first(PROTAGONIST);
  loop1: for (;;) {
    if (!x) {
      break loop1;
    } else if (hasFlag(x, WORNBIT)) {
      clearFlag(x, WORNBIT);
    }
    n_ = next(x);
    x = n_;
  }
  move(RETICULE, PROTAGONIST);
  setFlag(SHOES, WORNBIT);
  setFlag(CHEMISE, WORNBIT);
  clearFlag(CHEMISE, EVERYBIT);
  g.BOY_DRESS$ = false;
  return true;
}

