async function PRE_PUT() {
  if (g.PRSI == GROUND) {
    await PERFORM(V.DROP, g.PRSO);
    return true;
  } else if (g.PRSO == WINE || g.PRSO == LAUD) {
    await PERFORM(V.POUR, g.PRSO, g.PRSI);
    return true;
  } else if (g.PRSO == HANDS) {
    if (isVerb(V.PUT)) {
      await PERFORM(V.REACH_IN, g.PRSI);
      return true;
    } else {
      return await WASTES();
    }
  } else if ((g.PRSI == SEA) && (g.HERE == RIGGING_ROOM || g.HERE == CROWS_NEST || g.HERE == BOWSPRIT || g.HERE == POOP || g.HERE == QUARTERDECK || g.HERE == MAIN_DECK || g.HERE == FOCSLE) && isVerb(V.THROW, V.DROP, V.PUT_ON, V.PUT)) {
    return false;
  } else if (hasFlag(g.PRSI, ACTORBIT) && !(isVerb(V.PUT_ON))) {
    return await WASTES();
  } else if (await HELD$(g.PRSI, g.PRSO)) {
    tell(S(g.YOU_CANT), "put");
    await TPRINT_PRSO();
    if (eq(get(g.P_ITBL, P_PREP2), PR.ON)) {
      tell(" on");
    } else {
      tell(" in");
    }
    await TPRINT_PRSI();
    tell(" when");
    await TPRINT_PRSI();
    tell(" is already ");
    if (hasFlag(g.PRSO, SURFACEBIT)) {
      tell("on");
    } else {
      tell("in");
    }
    await TPRINT_PRSO();
    tell("!\n");
    return true;
  } else if (!(await HELD$(g.PRSO)) && !(g.PRSO == MANACLES)) {
    tell(S(g.YNH));
    await TRPRINT(g.PRSO);
    return true;
  } else if (await UNTOUCHABLE$(g.PRSI)) {
    return await CANT_REACH(g.PRSI);
  } else if (await IDROP()) {
    return true;
  } else {
    return false;
  }
}

async function V_PUT() {
  if (!(hasFlag(g.PRSI, OPENBIT)) && !(hasFlag(g.PRSI, CONTBIT)) && !(hasFlag(g.PRSI, SURFACEBIT)) && !(hasFlag(g.PRSI, VEHBIT))) {
    tell(S(g.YOU_CANT), "put");
    await TPRINT_PRSO();
    tell(" in");
    await APRINT(g.PRSI);
    tell("!\n");
    return true;
  } else if ((g.PRSI == g.PRSO) || ((await HELD$(g.PRSO)) && !(hasFlag(g.PRSO, TAKEBIT)))) {
    return await WASTES();
  } else if (hasFlag(g.PRSI, DOORBIT)) {
    tell(S(g.CANT_FROM_HERE));
    return true;
  } else if (!(hasFlag(g.PRSI, OPENBIT)) && !(hasFlag(g.PRSI, SURFACEBIT))) {
    await THIS_IS_IT(g.PRSI);
    return (await DO_FIRST("open", g.PRSI));
  } else if (loc(g.PRSO) == g.PRSI) {
    tell("But");
    await TPRINT_PRSO();
    tell(" is already in");
    await TRPRINT(g.PRSI);
    return true;
  } else if (((((await WEIGHT(g.PRSI)) + (await WEIGHT(g.PRSO))) - getProp(g.PRSI, P.SIZE)) > getProp(g.PRSI, P.CAPACITY)) && !(await HELD$(g.PRSO, g.PRSI))) {
    tell("There's no room ");
    if (hasFlag(g.PRSI, SURFACEBIT)) {
      tell("on");
    } else {
      tell("in");
    }
    await TPRINT_PRSI();
    tell(" for");
    await TRPRINT(g.PRSO);
    return true;
  } else if (!(await HELD$(g.PRSO)) && eq(await ITAKE(false), M_FATAL, false)) {
    return true;
  } else {
    move(g.PRSO, g.PRSI);
    setFlag(g.PRSO, TOUCHBIT);
    tell("Done.\n");
    return true;
  }
}

