async function IDROP() {
  if (g.PRSO == HANDS) {
    if (isVerb(V.DROP, V.THROW, V.GIVE)) {
      return await IMPOSSIBLES();
    } else {
      return false;
    }
  } else if (g.PRSO == RETICULE) {
    if (isVerb(V.DROP, V.THROW, V.GIVE)) {
      tell("A lady is never without her reticule.\n");
      return true;
    } else {
      return false;
    }
  } else if ((g.PRSO == ME) && isVerb(V.PUT) && hasFlag(g.PRSI, ACTORBIT)) {
    await PERFORM(V.BOARD, g.PRSI);
    return true;
  } else if ((g.PRSI == ME) && isVerb(V.PUT) && hasFlag(g.PRSO, ACTORBIT)) {
    await PERFORM(V.BOARD, g.PRSO);
    return true;
  } else if (((g.PRSO == SPICES) || (g.PRSO == PINCH)) && (await HELD$(PINCH))) {
    return false;
  } else if (!(await HELD$(g.PRSO))) {
    if ((g.PRSO == ME) || hasFlag(g.PRSO, BODYBIT)) {
      await IMPOSSIBLES();
    } else {
      tell(S(g.YNH));
      await TRPRINT(g.PRSO);
    }
    return M_FATAL;
  } else if (!(loc(g.PRSO) == PROTAGONIST) && hasFlag(loc(g.PRSO), CONTBIT) && !(hasFlag(loc(g.PRSO), OPENBIT))) {
    return (await DO_FIRST("open", loc(g.PRSO)));
  } else if (hasFlag(g.PRSO, WORNBIT)) {
    return (await DO_FIRST("remove", g.PRSO));
  } else {
    return false;
  }
}

async function CCOUNT(obj) {
  let cnt = 0, x = 0;
  if (x = first(obj)) {
    loop1: for (;;) {
      if (!(hasFlag(x, WORNBIT))) {
        cnt = cnt + 1;
      }
      if (!(x = next(x))) {
        break loop1;
      }
    }
  }
  return cnt;
}

async function WEIGHT(obj) {
  let cont = 0, wt = 0;
  if (cont = first(obj)) {
    loop1: for (;;) {
      wt = wt + (await WEIGHT(cont));
      if (!(cont = next(cont))) {
        break loop1;
      }
    }
  }
  return wt + getProp(obj, P.SIZE);
}

