async function GOTO(new_loc, dont_describe_dad = false) {
  let old_here = 0;
  old_here = g.HERE;
  move(PROTAGONIST, new_loc);
  if (loc(new_loc) == ROOMS) {
    g.HERE = new_loc;
  } else {
    g.HERE = loc(new_loc);
  }
  g.LIT = await LIT$(g.HERE);
  if ((old_here == LIBRARY) && (await HELD$(HAT)) && (g.HERE == BY_HOUSE || g.HERE == HALL_E)) {
    await SAFETY_SAKE();
    crlf();
  }
  await apply(getProp(g.HERE, P.ACTION), M_ENTER);
  if ((g.HERE == PASSAGE_4) && (loc(DAD) == g.HERE)) {
    tell("\"What a brave tot! You've inherited all your mother's spirit.\" Your father beams with pride", S(g.PCR), "\n");
  } else if ((g.HERE == BOTTOM_STAIRS) && (loc(COOKIE) == ANTEROOM)) {
    g.COOKIE_FIGHTING_CROC = false;
    clearFlag(CROC, NDESCBIT);
    tell("\"I ain't goin' to fight this beast if you're headin' back upstairs.\"");
    await TPRINT(COOKIE);
    if (loc(RAPIER) == PROTAGONIST) {
      move(RAPIER, COOKIE);
      tell(" eyes");
      await TPRINT(RAPIER);
      tell(" in");
      await TPRINT(HANDS);
      tell(". \"Not a proper thing fer a lady,\" he grumbles, taking it from you. He");
    }
    tell(" follows you", S(g.PCR), "\n");
  } else if (g.HERE == LAGOON) {
    return true;
  }
  if ((await DESCRIBE_ROOM()) && !(g.VERBOSITY == 0)) {
    await DESCRIBE_OBJECTS();
  }
  if ((loc(DAD) == old_here) && (loc(PROTAGONIST) == g.HERE) && !dont_describe_dad && !g.ENDGAME) {
    await DAD_FOLLOWS_YOU();
  }
  if ((loc(HERO) == old_here) && (loc(PROTAGONIST) == g.HERE) && !g.ENDGAME) {
    if ((g.HERE == BALLROOM) && (g.PARTNER == HERO)) {
      move(HERO, g.HERE);
      tell(D(HERO), " smiles and follows you, pulling you onto", S(DANCE_FLOOR), S(g.PCR));
    } else if (old_here == BALLROOM) {
      move(HERO, g.HERE);
      return true;
    } else {
      await STOP_QUEUES();
      remove(HERO);
      tell(S(g.INDENT), "\"No, wait -- !\" Jamison cries. He ");
      if (g.HERE == LAWN) {
        tell("slips past you into the forest");
      } else {
        tell("hesitates and turns away");
      }
      tell(S(g.PCR));
    }
  }
  if (g.ENDGAME && (loc(COOKIE) == old_here) && (loc(PROTAGONIST) == g.HERE) && !g.COOKIE_FIGHTING_CROC && !(await RUNNING$(I_ENDGAME.id))) {
    if ((await RUNNING$(I_DUEL.id)) && (old_here == GALLERY || old_here == STAIRTOP)) {
      return true;
    } else if (g.HERE == BEACH) {
      return true;
    }
    move(COOKIE, g.HERE);
    tell(S(g.INDENT), D(COOKIE), " pegs after you", S(g.PCR));
  }
  return true;
}

