async function NOT_HERE_OBJECT_F() {
  let tbl = 0, prso$ = true, obj = 0, x = false;
  if ((g.PRSO == NOT_HERE_OBJECT) && (g.PRSI == NOT_HERE_OBJECT)) {
    tell("Those things aren't here!\n");
    return true;
  } else if ((g.P_XNAM == W.MOUTH || g.P_XNAM == W.EYES) && (g.P_XADJN == W.LAFOND || g.P_XADJN == false)) {
    if (g.PRSO == NOT_HERE_OBJECT) {
      g.PRSO = LAFOND;
    } else {
      g.PRSI = LAFOND;
    }
    return false;
  } else if ((g.P_XADJN == W.POWDER) && (await HELD$(HORN))) {
    if (g.PRSO == NOT_HERE_OBJECT) {
      g.PRSO = POWDER;
    } else {
      g.PRSI = POWDER;
    }
  } else if (((g.P_XNAM == W.HANDS || g.P_XNAM == W.HAND) || (g.P_XNAM == W.FINGER || g.P_XNAM == W.EYE || g.P_XNAM == W.EYES) || (g.P_XNAM == W.HEAD || g.P_XNAM == W.JAMISON) || (g.P_XNAM == W.LIP || g.P_XNAM == W.LIPS || g.P_XNAM == W.MOUTH)) && ((g.P_XADJN == W.NICK || g.P_XADJN == W.NICHOLAS || g.P_XADJN == W.CROC_S) || (g.P_XADJN == W.DAD || g.P_XADJN == W.FATHER || g.P_XADJN == W.PAPA) || (g.P_XADJN == W.WOMAN || g.P_XADJN == W.LUCY) || (g.P_XADJN == W.JEAN || g.P_XADJN == W.LAFOND))) {
    tell("[Sadly, we haven't the space to handle everything. Try to refer only to characters in the story, not individual body parts or possessions. For example, you can EXAMINE PIRATE but you can't EXAMINE PIRATE'S EYEPATCH.]\n");
    return true;
  } else if (g.PRSO == NOT_HERE_OBJECT) {
    tbl = g.P_PRSO;
  } else {
    tbl = g.P_PRSI;
    prso$ = false;
  }
  if (prso$ && (await PRSO_MOBY_VERB$())) {
    x = true;
  } else if (!prso$ && (await PRSI_MOBY_VERB$())) {
    x = true;
  }
  if (x) {
    if (obj = await FIND_NOT_HERE(tbl, prso$)) {
      if (!(obj == NOT_HERE_OBJECT)) {
        return true;
      }
    } else {
      return false;
    }
    if (isVerb(V.WALK_TO, V.FOLLOW)) {
      await V_WALK_AROUND();
    } else {
      await MORE_SPECIFIC();
    }
  } else {
    if (g.WINNER == PROTAGONIST) {
      tell("You");
    } else if (hasFlag(g.WINNER, DEADBIT)) {
      tell(S(g.DOESNT_RESPOND));
      return M_FATAL;
    } else {
      tell("Looking confused,");
      await TPRINT(g.WINNER);
      tell(" says, \"I");
    }
    tell(" can't see");
    if (!(await ADJNAME$(g.P_XADJ)) && !(await NAME$(g.P_XNAM))) {
      tell(" any");
    }
    await NOT_HERE_PRINT(prso$);
    tell(" here!");
    if (!(g.WINNER == PROTAGONIST)) {
      tell("\"");
    }
    crlf();
  }
  return await STOP();
}

