async function FIND_NOT_HERE(tbl, prso$) {
  let m_f = 0, obj = 0;
  m_f = await MOBY_FIND(tbl);
  if (1 == m_f) {
    if (prso$) {
      g.PRSO = g.P_MOBY_FOUND;
      await THIS_IS_IT(g.PRSO);
    } else {
      g.PRSI = g.P_MOBY_FOUND;
    }
    return false;
  } else if ((1 < m_f) && (obj = await apply(getProp(obj = getb(tbl, 1), P.GENERIC)))) {
    if (obj == NOT_HERE_OBJECT) {
      return true;
    } else if (prso$) {
      g.PRSO = obj;
      await THIS_IS_IT(g.PRSO);
    } else {
      g.PRSI = obj;
    }
    return false;
  } else {
    return NOT_HERE_OBJECT;
  }
}

async function NOT_HERE_PRINT(prso$) {
  if (g.P_OFLAG) {
    if (g.P_XADJ) {
      tell(" ");
      printB(g.P_XADJN);
    }
    if (g.P_XNAM) {
      tell(" ");
      return printB(g.P_XNAM);
    } else {
      return false;
    }
  } else if (prso$) {
    return await BUFFER_PRINT(get(g.P_ITBL, P_NC1), get(g.P_ITBL, P_NC1L), false);
  } else {
    return await BUFFER_PRINT(get(g.P_ITBL, P_NC2), get(g.P_ITBL, P_NC2L), false);
  }
}

async function LADDER_F() {
  if (!g.LADDER_HANGING) {
    return await CANT_SEE(LADDER);
  } else if (isVerb(V.TAKE, V.CLIMB, V.BOARD)) {
    if (eq(loc(PROTAGONIST), CAPT_QUARTERS)) {
      if (hasFlag(LEDGE, MUNGBIT)) {
        tell("You lean over");
        await TPRINT(LEDGE);
        tell(", but");
        await TPRINT(LADDER);
        tell(" is too far out to reach", S(g.PCR));
        return true;
      } else {
        tell("It's on the other side of the window", S(g.PCR));
        return true;
      }
    } else if (eq(loc(PROTAGONIST), LEDGE)) {
      tell("You ");
      if (await ANYTHING_HELD()) {
        await ROB(PROTAGONIST, RETICULE);
        tell("put everything in");
        await TPRINT(RETICULE);
        tell(" and ");
      }
      if (hasFlag(POOP, TOUCHBIT)) {
        tell("hop out, catching the");
      } else {
        await QUEUE(I_LADDER_BLOWS.id, -1);
        tell("reach out for");
        await TPRINT(LADDER);
        tell(" and over-balance, tumbling from your perch. Your hand closes on a slimy hemp rung as you fly out over the waves, clinging tenuously, feet free, to the");
      }
      await PRSO_PRINT();
      tell(S(g.PCR), "\n");
      return await GOTO(ON_LADDER);
    } else if ((g.HERE == ON_LADDER) && isVerb(V.TAKE)) {
      tell(S(g.HOLDING_IT));
      return true;
    } else if (eq(loc(PROTAGONIST), SKIFF)) {
      return await DEBARK_SKIFF();
    } else if (g.HERE == POOP) {
      tell("If you wish to climb down");
      await TPRINT(LADDER);
      tell(", say so", S(g.PCR));
      return true;
    } else {
      return await DO_WALK(P.UP);
    }
  } else if (isVerb(V.CUT)) {
    if (await HELD$(DAGGER)) {
      await CTPRINT(DAGGER);
      tell(" isn't sharp enough to cut through");
      await TRPRINT(LADDER);
      return true;
    } else {
      return await PROPOSE();
    }
  } else if (isVerb(V.UNTIE)) {
    await CTPRINT(ROPE);
    tell(" is tied in too complex a knot", S(g.PCR));
    return true;
  } else if (isVerb(V.CLIMB_DOWN)) {
    if (g.HERE == CAPT_QUARTERS) {
      return (await DO_FIRST("get on", LADDER));
    } else {
      await DO_WALK(P.DOWN);
      return true;
    }
  } else if (isVerb(V.EXAMINE) && (g.HERE == CAPT_QUARTERS || g.HERE == ON_LADDER || g.HERE == POOP)) {
    tell(S(g.COMMON_LOOKING), "rope ", D(LADDER), S(g.PCR));
    return true;
  } else {
    return false;
  }
}

async function I_END_PROLOGUE() {
  tell(S(g.INDENT), "Davis leaps across the deck to your side, \"Free me or she dies!\" he yells, jabbing a knife up to your throat. In one smooth motion,");
  await TPRINT(HERO);
  tell(" draws his rapier, pulls you free and stabs. Davis slumps into a bloody heap.\n   Swooning, you fall into the Falcon's arms. You are dimly aware of being carried to the other ship, down a short flight of stairs, and laid gently on a soft bed. When you gather strength to look around, the Falcon has left you in peace.\n   You remain confined to this room, a large cupboard blocking the door. Meals are brought by a peg-legged old man and eaten in silence. Of your handsome rescuer you see nothing. Slowly the days pass.\n");
  tell("\n", S(g.HIT_RETURN), "continue.]\n");
  await read(g.P_INBUF, g.P_LEXV);
  await CLEAR_SCREEN(10);
  await GOTO(CAPT_QUARTERS);
  clearFlag(CRULLEY, DEADBIT);
  clearFlag(DOOR, MUNGBIT);
  move(HERO, CAPT_QUARTERS);
  clearFlag(HERO, NDESCBIT);
  remove(COFFER);
  setFlag(COFFER, MUNGBIT);
  clearFlag(COFFER, LOCKEDBIT);
  setFlag(RAPIER, NDESCBIT);
  return clearFlag(DOOR, OPENBIT);
}

