async function DOOR_F() {
  if (g.HERE == CAPT_QUARTERS) {
    await PERFORM_PRSA(CURTAIN);
    return true;
  } else if (isVerb(V.EXAMINE, V.LOOK_INSIDE)) {
    if (await NOUN_USED(W.LOCK, LDOOR)) {
      tell("Ladies do not look through keyholes!\n");
    } else if (hasFlag(g.PRSO, OPENBIT)) {
      tell("It is open");
    } else {
      tell("It", S(g.IS_CLOSED));
      if (g.HERE == QUARTERDECK) {
        tell(" and barred");
      } else if (hasFlag(DOOR, MUNGBIT)) {
        tell(". Or, what remains of it is");
      }
    }
    await THIS_IS_IT(g.PRSO);
    tell(S(g.PCR));
    return true;
  } else if (isVerb(V.PICK) && (g.PRSO == LDOOR)) {
    tell("The mechanism is too complex to pick.\n");
    return true;
  } else if (isVerb(V.UNLOCK)) {
    if (g.HERE == UPPER_HALL_E) {
      tell("Only one man has the key to this room: Jean Lafond", S(g.PCR));
      return true;
    } else if (g.HERE == QUARTERDECK) {
      await PERFORM(V.OPEN, DOOR);
      return true;
    } else if (g.PRSO == WOOD_CELL_DOOR) {
      tell("But");
      await TPRINT(DOOR);
      tell(" isn't locked", S(g.PCR));
      return true;
    } else if (g.PRSI == LARGE_KEY) {
      if (g.PRSO == IRON_CELL_DOOR) {
        clearFlag(g.PRSO, LOCKEDBIT);
        tell("Unlocked", S(g.PCR));
        return true;
      } else {
        tell("That key does not unlock this door", S(g.PCR));
        return true;
      }
    } else {
      tell("You are unable to unlock");
      await TRPRINT(DOOR);
      return true;
    }
  } else if (isVerb(V.LOCK)) {
    if ((g.PRSO == IRON_CELL_DOOR) && (g.PRSI == LARGE_KEY)) {
      setFlag(g.PRSO, LOCKEDBIT);
      tell("You ");
      if (hasFlag(g.PRSO, OPENBIT)) {
        clearFlag(g.PRSO, OPENBIT);
        tell("close and ");
      }
      tell("lock");
      await TRPRINT(DOOR);
      return true;
    } else if (g.PRSI == LARGE_KEY) {
      tell("That key won't work here", S(g.PCR));
      return true;
    } else if (g.PRSO == VER_DOOR) {
      tell(S(g.YOU_CANT), "lock that", S(g.PCR));
      return true;
    } else {
      return await PROPOSE();
    }
  } else if (isVerb(V.KNOCK)) {
    if ((g.HERE == UPPER_HALL_E) && !(hasFlag(LDOOR, LOCKEDBIT)) && (loc(LAFOND) == LAFS_ROOM)) {
      tell(D(LAFOND), " calls, \"Come.\"\n");
      return true;
    } else {
      tell("Silence answers back.\n");
      return true;
    }
  } else if (isVerb(V.OPEN)) {
    if (g.HERE == CABIN) {
      tell("It appears to be locked.\n");
      return true;
    } else if (g.HERE == LANDING) {
      await CTPRINT(DOOR);
      tell(" won't open", S(g.PCR));
      return true;
    } else if (g.HERE == QUARTERDECK) {
      tell("Someone yells from ahead, \"Cap'n 'll have your hide if you go down there!\" You haven't the strength to lift the bar anyway", S(g.PCR));
      return true;
    } else if ((g.HERE == VERANDA) && !(hasFlag(DOOR, OPENBIT))) {
      tell(S(g.YOU_CANT_SEE_ANY), S(g.WAY_TO_DO_THAT));
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

