async function WATER_F() {
  if (((g.HERE == LAFS_ROOM || g.HERE == RIGGING_ROOM) || (g.HERE == BOWSPRIT || g.HERE == CROWS_NEST)) && !(isVerb(V.THROW, V.PUT, V.PUT_ON))) {
    if (isVerb(V.ENTER)) {
      tell(S(g.SUICIDE));
      return true;
    } else {
      return await CANT_REACH(SEA);
    }
  } else if (!((await GLOBAL_IN$(SEA, g.HERE)) || (await HELD$(WATER, g.HERE)))) {
    tell("There's no water here.\n");
    return true;
  } else if (isVerb(V.LOOK_INSIDE, V.LOOK_UNDER, V.EXAMINE)) {
    tell("The water is sparkling clear", S(g.PCR));
    return true;
  } else if (isVerb(V.REACH_IN)) {
    tell("Water", S(g.DRIPS_OFF));
    return true;
  } else if (isVerb(V.DRINK, V.DRINK_FROM)) {
    if (g.PRSO == WATER) {
      tell("You take a long draft. It is quite refreshing", S(g.PCR));
      return true;
    } else {
      tell("This water is much too salty to drink", S(g.PCR));
      return true;
    }
  } else if (isVerb(V.PUT_ON) && (g.PRSI == SEA)) {
    await PERFORM(V.PUT, g.PRSO, SEA);
    return true;
  } else if (isVerb(V.THROW)) {
    if ((g.HERE == CAPT_QUARTERS) && !(hasFlag(LEDGE, MUNGBIT))) {
      tell("But");
      await TPRINT(WINDOW);
      tell(S(g.IS_CLOSED), "!\n");
      return true;
    } else {
      remove(g.PRSO);
      tell("You toss");
      await TPRINT_PRSO();
      tell(" into");
      await TRPRINT(SEA);
      return true;
    }
  } else if (isVerb(V.PUT, V.SOAK)) {
    if (g.PRSO == INVITE || g.PRSO == LETTER) {
      remove(g.PRSO);
      tell("It disintegrates quickly into nothing", S(g.PCR));
      return true;
    } else if (g.HERE == POOP || g.HERE == QUARTERDECK || g.HERE == FOCSLE || g.HERE == BOWSPRIT || g.HERE == CAPT_QUARTERS) {
      await PERFORM(V.THROW, g.PRSO, SEA);
      return true;
    } else if (g.HERE == MAIN_DECK) {
      if (g.PRSI == SEA) {
        await PERFORM(V.THROW, g.PRSO, SEA);
        return true;
      } else {
        await PERFORM(V.PUT, g.PRSO, WATER_BARREL);
        return true;
      }
    } else if (g.HERE == BEACH || g.HERE == SHALLOWS || g.HERE == LAGOON || g.HERE == BY_SHIP) {
      if (g.PRSO == DRESS || g.PRSO == RAG) {
        return await DIP_DRESS();
      } else {
        tell("You dip");
        await TPRINT_PRSO();
        tell(" into the water", S(g.PCR));
        return true;
      }
    } else {
      tell(S(g.YOU_CANT), "reach any water", S(g.PCR));
      return true;
    }
  } else if (isVerb(V.BOARD, V.ENTER, V.SWIM)) {
    if (g.HERE == BEACH) {
      return await DO_WALK(P.EAST);
    } else {
      return await V_SWIM();
    }
  } else if (await TOUCHING$(SEA)) {
    tell("The cool water runs through your fingers", S(g.PCR));
    return true;
  } else {
    return false;
  }
}

