async function BED_F(varg = false) {
  let this_bed = 0;
  if (varg) {
    if ((varg == M_BEG) && (isVerb(V.WALK) || (g.PRSO && isVerb(V.TAKE) && !(g.PRSO == HRING || g.PRSO == LRING) && !(loc(g.PRSO) == GLOBAL_OBJECTS) && !(eq(loc(PROTAGONIST), loc(g.PRSO)))))) {
      (await DO_FIRST("stand up"));
      return M_FATAL;
    } else {
      return false;
    }
  } else if (isVerb(V.DISEMBARK, V.STAND) && (loc(LAFOND) == LAFS_BED)) {
    tell("Lafond slams you back into the feather mattress", S(g.PCR));
    return true;
  } else if (isVerb(V.ENTER, V.BOARD) && eq(loc(PROTAGONIST), LAFS_ROOM) && (loc(LAFOND) == g.HERE)) {
    tell(D(LAFOND), " stops you. \"I'll tell you when to do that.\"\n");
    return true;
  } else if (isVerb(V.EXAMINE)) {
    if ((this_bed = g.HERE == CABIN ? CABIN_BED : (g.HERE == CAPT_QUARTERS ? CAPT_BED : false)) && !(first(this_bed))) {
      tell("Someone appears to have tumbled out of it in a hurry");
    } else if (g.HERE == LAFS_ROOM) {
      tell("You gaze at the purple and gold bed, fearing it is your destiny");
    } else if (g.HERE == CELL_1) {
      tell("It is an uncomfortable canvas cot, old and torn");
    } else {
      return false;
    }
    tell(S(g.PCR));
    return true;
  } else if (isVerb(V.LOOK_UNDER)) {
    if (await QUEUED$(I_COFFER.id)) {
      tell(S(g.YOU_SEE));
      await APRINT(COFFER);
      tell(" ");
      clearFlag(COFFER, NDESCBIT);
      setFlag(COFFER, TOUCHBIT);
    } else {
      tell(S(g.THERES_NOTHING));
    }
    tell("under");
    await TRPRINT(g.PRSO);
    return true;
  } else if (isVerb(V.MOVE, V.PUSH)) {
    tell("It is nailed to the floor", S(g.PCR));
    return true;
  } else if (isVerb(V.PUT_UNDER) && (g.HERE == CAPT_QUARTERS || g.HERE == CABIN)) {
    if (g.PRSO == ME) {
      await PERFORM(V.CRAWL_UNDER, CABIN_BED);
      return true;
    } else if (g.PRSO == RETICULE) {
      return false;
    } else {
      tell("You do so, but the ship rolls to one side and");
      await TPRINT_PRSO();
      tell(" rolls out", S(g.PCR));
      return move(g.PRSO, g.HERE);
    }
  } else {
    return false;
  }
}

