async function TOUCHING$(thing) {
  if ((g.PRSO == thing) && ((g.PRSA == V.ALARM || g.PRSA == V.BITE || g.PRSA == V.BOARD) || (g.PRSA == V.CLEAN || g.PRSA == V.CLIMB_OVER || g.PRSA == V.CRAWL_UNDER) || (g.PRSA == V.CLIMB || g.PRSA == V.CLIMB_DOWN || g.PRSA == V.CLIMB_ON) || (g.PRSA == V.CUT || g.PRSA == V.DANCE || g.PRSA == V.EMBRACE) || (g.PRSA == V.ENTER || g.PRSA == V.FIDDLE) || (g.PRSA == V.KICK || g.PRSA == V.KILL || g.PRSA == V.KISS) || (g.PRSA == V.KNOCK || g.PRSA == V.LOOK_UNDER || g.PRSA == V.LOOK_INSIDE) || (g.PRSA == V.MOVE || g.PRSA == V.MUNG || g.PRSA == V.WRING) || (g.PRSA == V.ON || g.PRSA == V.OFF || g.PRSA == V.OPEN || g.PRSA == V.CLOSE) || (g.PRSA == V.PICK || g.PRSA == V.PUSH || g.PRSA == V.RAISE) || (g.PRSA == V.SET || g.PRSA == V.STAND_ON || g.PRSA == V.SWIM || g.PRSA == V.TIE) || (g.PRSA == V.THROW || g.PRSA == V.RAPE) || (g.PRSA == V.TAKE || g.PRSA == V.TOUCH || g.PRSA == V.SHAKE) || (g.PRSA == V.UNLOCK || g.PRSA == V.LOCK || g.PRSA == V.UNTIE))) {
    return true;
  } else if ((g.PRSI == thing) && isVerb(V.GIVE, V.PUT, V.PUT_ON, V.PUT_UNDER)) {
    return true;
  } else {
    return false;
  }
}

