async function SHIP_F() {
  if (isVerb(V.EXAMINE)) {
    if (await SHIP_BOARD(g.HERE)) {
      return await V_LOOK();
    } else if (g.HERE == CABIN || g.HERE == DEUX_DECK) {
      if ((await ADJ_USED(A.HELENA)) || (await NOUN_USED(W.LOUISE, SHIP))) {
        await PERFORM(V.LOOK_INSIDE, WINDOW);
        return true;
      } else {
        return await V_LOOK();
      }
    } else if ((g.HERE == CELL_1 || g.HERE == CELL_2) || (g.HERE == LAFS_ROOM || g.HERE == BEACH || g.HERE == LAGOON || g.HERE == SHALLOWS)) {
      if (hasFlag(SHIP, MUNGBIT)) {
        tell(S(g.YOU_CANT), "see");
        await TPRINT(SHIP);
        tell(" anywhere, but a lot of debris floats in the lagoon", S(g.PCR));
        return true;
      } else {
        await CTPRINT(SHIP);
        tell(" floats, silent and serene, some distance out in the lagoon", S(g.PCR));
        return true;
      }
    } else {
      tell(S(g.YOU_CANT), "see");
      await TPRINT(SHIP);
      tell(" from here.\n");
      return true;
    }
  } else if (isVerb(V.POINT)) {
    if (!g.PRSI) {
      return await PROPOSE();
    } else {
      return false;
    }
  } else if (isVerb(V.PUT) && (g.PRSO == TRAY || g.PRSO == MIRROR)) {
    return await IMPOSSIBLES();
  } else {
    return false;
  }
}

