async function I_LOOK_SEA(called_by_interrupt = true) {
  let cant_see_reefs = 0;
  if (await INNER_DECK(g.HERE)) {
    cant_see_reefs = true;
  }
  if (called_by_interrupt) {
    await QUEUE(I_LOOK_SEA.id, 15);
    g.SHIP_LOC = g.SHIP_LOC + 1;
    if (g.SHIP_LOC == 10) {
      tell(S(g.INDENT), S(get(g.REEF_DESC, g.SHIP_LOC)));
      return (await FWTD(". The next few minutes last forever as havoc breaks out. Grabbing a plank, you manage to stay afloat, but you are washed out to sea. A brig, Portuguese by its sails, rescues you. The sailors are brown skinned and smooth, and the first mate, the ship's and yours, is gentle. They leave you in Rio, alone and forgotten."));
    } else if (cant_see_reefs) {
      if (g.SHIP_LOC == 8) {
        tell(S(g.INDENT), "The crash of surf is increasing in volume. You'd best find out what's going on!\n");
        return true;
      } else {
        return false;
      }
    } else {
      tell(S(g.INDENT), S(get(g.REEF_DESC, g.SHIP_LOC)), S(g.PCR));
      return true;
    }
  } else if (!(hasFlag(ANCHOR, MUNGBIT))) {
    return true;
  } else if (await RUNNING$(I_LOOK_SEA.id)) {
    await QUEUE(I_LOOK_SEA.id, 2);
    return await I_LOOK_SEA(false);
  } else {
    tell("\n", S(g.INDENT), S(get(g.REEF_DESC, g.SHIP_LOC)), ".");
    return true;
  }
}

async function I_CURRENT() {
  let venue = 0;
  venue = loc(PROTAGONIST) == CASK ? (g.CASK_LOC + g.ROWING) : (loc(PROTAGONIST) == SKIFF ? (g.SKIFF_LOC + g.ROWING) : false);
  if (g.ROWING == (-1)) {
    tell(S(g.INDENT), "The current pulls you in towards the island.");
    if (g.HERE == BY_SHIP) {
      crlf();
      crlf();
      move(SKIFF, LAGOON);
      await GOTO(SKIFF);
      await V_LOOK();
    } else if ((venue < 2) && !(g.HERE == SHALLOWS)) {
      venue = 1;
      await DEQUEUE(I_CURRENT.id);
      tell(" With a scrape,");
      await TPRINT(loc(PROTAGONIST));
      tell(" lodges in the sand", S(g.PCR), "\n");
      if (loc(PROTAGONIST) == CASK) {
        move(CASK, SHALLOWS);
        await GOTO(CASK);
      } else if (loc(PROTAGONIST) == SKIFF) {
        move(SKIFF, SHALLOWS);
        await GOTO(SKIFF);
      }
    } else if (g.HERE == LAGOON) {
      crlf();
      if (!g.LOOKED_LAGOON$) {
        await V_LOOK();
      } else {
        g.LOOKED_LAGOON$ = false;
      }
    } else {
      return true;
    }
  }
  g.ROWING = -1;
  if (loc(PROTAGONIST) == CASK) {
    g.CASK_LOC = venue;
  } else if (loc(PROTAGONIST) == SKIFF) {
    g.SKIFF_LOC = venue;
  }
  return true;
}

async function SKIFF_F(varg = false) {
  let str = false;
  if (varg) {
    if (varg == M_DESC$) {
      return true;
    } else if (varg == M_OBJDESC) {
      tell(S(g.INDENT));
      if (hasFlag(SKIFF, TOUCHBIT)) {
        await CTPRINT(SKIFF);
      } else {
        setFlag(SKIFF, TOUCHBIT);
        tell("A ", D(SKIFF));
      }
      tell(" nods in the waves, its oars jerking around in the current.");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.EXAMINE)) {
    await CTPRINT(SKIFF);
    tell(" is large enough to carry several men, but light enough that you feel able to row it", S(g.PCR));
    return true;
  } else if (isVerb(V.LOOK_INSIDE)) {
    clearFlag(OARS, NDESCBIT);
    if (loc(PROTAGONIST) == SKIFF) {
      await DESCRIBE_VEHICLE();
    } else {
      tell("In");
      await TPRINT(SKIFF);
      tell(" is");
      await DESCRIBE_CONTENTS(SKIFF);
      tell(S(g.PCR));
    }
    return setFlag(OARS, NDESCBIT);
  } else if (isVerb(V.LAUNCH) || (isVerb(V.PUSH) && (g.PRSI == SEA))) {
    tell(S(g.ALREADY_IS));
    return true;
  } else if (isVerb(V.TIE)) {
    if (g.HERE == BY_SHIP) {
      return await DEBARK_SKIFF();
    } else {
      tell(S(g.THERES_NOTHING), "to moor it to!\n");
      return true;
    }
  } else if (isVerb(V.ROW)) {
    if (eq(loc(PROTAGONIST), SKIFF)) {
      if (g.HERE == BEACH) {
        return (await DO_FIRST("launch", SKIFF));
      } else {
        tell(S(g.YOULL_HAVE_TO), "specify a ", D(INTDIR), S(g.PCR));
        return true;
      }
    } else {
      return (await DO_FIRST("get in", SKIFF));
    }
  } else if (isVerb(V.DISEMBARK)) {
    if (g.HERE == LAGOON) {
      tell(S(TOO_DEEP));
      return true;
    } else if (g.HERE == BY_SHIP) {
      return await DEBARK_SKIFF();
    } else {
      return false;
    }
  } else if (isVerb(V.PUT_ON) && (g.PRSI == SKIFF)) {
    await PERFORM(V.PUT, g.PRSO, SKIFF);
    return true;
  } else {
    return false;
  }
}

