async function SALTS_F() {
  let per = false;
  if (isVerb(V.SMELL)) {
    tell("You jerk");
    await TPRINT(SALTS);
    tell(" away from your nose after one brief ammoniac whiff. Your burning nostrils make you feel more alert", S(g.PCR));
    return true;
  } else if (isVerb(V.WAVE)) {
    if ((g.HERE == DUNGEON) && hasFlag(HERO, DEADBIT)) {
      await PERFORM(V.ALARM, HERO, SALTS);
      return true;
    } else {
      await PERFORM(V.SMELL, SALTS);
      return true;
    }
  } else if (isVerb(V.USE)) {
    if (!g.PRSI) {
      if (((per = (await FIND_IN(g.HERE, ACTORBIT, "on"))) && !(per == CRULLEY))) {
        await PERFORM(V.ALARM, per, SALTS);
        return true;
      } else {
        await PERFORM(V.SMELL, SALTS);
        return true;
      }
    } else if (hasFlag(g.PRSI, ACTORBIT)) {
      await PERFORM(V.ALARM, g.PRSI, SALTS);
      return true;
    } else {
      tell(S(g.HUH));
      return true;
    }
  } else if (isVerb(V.PUT_UNDER, V.PUT_ON) && hasFlag(g.PRSI, ACTORBIT)) {
    await PERFORM(V.ALARM, g.PRSI, SALTS);
    return true;
  } else if (isVerb(V.GIVE)) {
    await PERFORM(V.ALARM, g.PRSI, SALTS);
    return true;
  } else if (isVerb(V.ALARM, V.SGIVE)) {
    if (g.PRSO == HERO) {
      return await REVIVE_HERO();
    } else if (g.PRSO == ME) {
      await PERFORM(V.SMELL, SALTS);
      return true;
    } else if ((g.PRSO == BUTLER) && hasFlag(BUTLER, DEADBIT)) {
      tell(S(g.YOU_CANT), "wake him", S(g.PCR));
      return true;
    } else if ((g.PRSO == CRULLEY) && hasFlag(CRULLEY, DEADBIT)) {
      g.AWAITING_REPLY = 2;
      await QUEUE(I_REPLY.id, 2);
      tell("Are you sure that's really wise?\n");
      return true;
    } else {
      await PRONOUN();
      tell(" doesn't need reviving", S(g.PCR));
      return true;
    }
  } else if (isVerb(V.EXAMINE)) {
    tell("You always carry your ", D(SALTS), ", for emergencies. There is a small tag on one side of them", S(g.PCR));
    return true;
  } else if (isVerb(V.READ)) {
    tell("It says, \"For cases of vapors, hysteria or collapse, revive persons with the smelling salts.\"\n");
    return true;
  } else {
    return false;
  }
}

async function REVIVE_HERO() {
  if (hasFlag(HERO, DEADBIT)) {
    g.SCORE = g.SCORE + 1;
    clearFlag(HERO, DEADBIT);
    tell("You wave");
    await TPRINT(SALTS);
    tell(" under Nicholas's nose. He stirs, sneezes and looks at you blearily. \"How --?\" he says, bewildered. \"Lafond, did he --?\" He ");
    if (!(hasFlag(CHEMISE, EVERYBIT))) {
      tell("looks at you in growing horror, glancing from your chemise to your face, and ");
    }
    tell("straightens. \"Darling, you are an angel, to have gone through all this and then rescue me. Your ravisher will not go unpunished.\" He squares his shoulders. \"For my brother, his wife, and your honor, I will kill Jean Lafond.\"\n");
    if (loc(HERO) == MANACLES) {
      g.AWAITING_REPLY = 13;
      await QUEUE(I_REPLY.id, 2);
      tell(S(g.INDENT), "He tugs at his chains with a wry smile. \"But I must get free first. Have you the key?\"\n");
      return true;
    } else {
      return await NICK_RUNS_OFF();
    }
  } else {
    tell("Jamison brushes you away, \"Thank you, but I'm not having the vapors.\"\n");
    return true;
  }
}

async function BOTTLE_F() {
  if (isVerb(V.OPEN, V.CLOSE)) {
    tell("This is a squeezable bottle. You don't need to open or close it", S(g.PCR));
    return true;
  } else if (isVerb(V.TAKE) && !(hasFlag(BOTTLE, TOUCHBIT)) && !(eq(await ITAKE(false), M_FATAL, false))) {
    g.SCORE = g.SCORE + 1;
    tell("Taken.\n");
    return true;
  } else if (isVerb(V.POUR, V.PUT) && (g.PRSI == BOTTLE)) {
    await PERFORM(V.FILL, BOTTLE, g.PRSO);
    return true;
  } else if (isVerb(V.DRINK_FROM, V.WRING) && (g.PRSO == BOTTLE)) {
    return await SQUEEZE_BOTTLE();
  } else if (isVerb(V.POUR_FROM, V.WRING) && (g.PRSO == LAUD)) {
    return (await SPECIFY_WHAT("put", LAUD));
  } else if (isVerb(V.DRINK_FROM)) {
    await PERFORM(V.WRING, LAUD, MOUTH);
    return true;
  } else if (isVerb(V.FILL)) {
    if (g.PRSI == BOTTLE) {
      await PERFORM(V.POUR, g.PRSI, g.PRSO);
      return true;
    } else {
      tell(S(g.YOU_CANT), "get anything into");
      await TRPRINT(BOTTLE);
      return true;
    }
  } else if (isVerb(V.EXAMINE, V.LOOK_INSIDE)) {
    tell("It's a small leather bottle, with a tiny label on one side");
    if (g.LAUD_LEFT > 0) {
      tell(". It appears to be almost empty");
    }
    tell(S(g.PCR));
    return true;
  } else if (isVerb(V.READ)) {
    tell("The label reads, \"Laudanum drops. Squeeze into a glass of wine to sleep free of pain and mental anguish.\"\n");
    return true;
  } else {
    return false;
  }
}

async function LAUD_F() {
  if (isVerb(V.POUR, V.PUT, V.WRING, V.PUT_ON) && (g.PRSO == LAUD)) {
    return await SQUEEZE_BOTTLE();
  } else if (isVerb(V.TAKE)) {
    tell("If you intend to drink");
    await TPRINT(LAUD);
    tell(", say so.\n");
    return true;
  } else if (isVerb(V.EAT, V.DRINK)) {
    await PERFORM(V.WRING, BOTTLE, ME);
    return true;
  } else if (g.PRSO == LAUD) {
    await PERFORM_PRSA(BOTTLE, g.PRSI);
    return true;
  } else if (g.PRSI == LAUD) {
    await PERFORM_PRSA(g.PRSO, BOTTLE);
    return true;
  } else {
    return false;
  }
}

async function SQUEEZE_BOTTLE() {
  if (g.PRSI == BOTTLE) {
    return await IMPOSSIBLES();
  } else if (hasFlag(g.PRSI, ACTORBIT)) {
    tell(S(g.POLITE));
    return true;
  } else if (g.PRSI == CROC) {
    await PERFORM(V.PUT, BOTTLE, CROC);
    return true;
  } else if ((g.LAUD_LEFT < 3) && !(g.HERE == LAFS_ROOM)) {
    tell("You stop, deciding you might need some later.\n");
    return true;
  } else if ((g.LAUD_LEFT = g.LAUD_LEFT - 1) > 0) {
    move(BOTTLE, PROTAGONIST);
    if (g.PRSI == ME) {
      await QUEUE(I_SLEEP.id, 2);
      putProp(ME, P.CONTENTS, POISONED);
      tell(S(g.SQUEEZE_DROPS), "into");
      await TPRINT(MOUTH);
      tell(".");
    } else if (g.PRSI == FLAGON) {
      putProp(FLAGON, P.CONTENTS, POISONED);
      await DOPE_WINE();
    } else if (g.PRSI == PORK) {
      g.PORK_DOPED = true;
      tell(S(g.SQUEEZE_DROPS), "onto");
      await TPRINT(PORK);
      tell(". A patch of salt dissolves as");
      await TPRINT(LAUD);
      tell(" absorbs into the meat.");
    } else if (g.PRSI == BLUE_GLASS || g.PRSI == GREEN_GLASS) {
      putProp(g.PRSI, P.CONTENTS, getProp(g.PRSI, P.CONTENTS) + POISONED);
      await DOPE_WINE();
    } else {
      tell(S(g.SQUEEZE_DROPS), "into");
      await TPRINT_PRSI();
      tell(".");
      if (hasFlag(g.PRSI, WEARBIT)) {
        tell(" It evaporates quickly.");
      }
    }
    if (g.LAUD_LEFT == 0) {
      tell(" From the feel of it, the bottle is now empty.");
    }
    crlf();
    return true;
  } else {
    return false;
  }
}

async function DOPE_WINE() {
  g.USED_LAUD = true;
  tell(S(g.SQUEEZE_DROPS), "into");
  await TPRINT_PRSI();
  tell(".");
  if (loc(LAFOND) == g.HERE) {
    tell(" You sense Lafond hesitate, then continue primping.");
  }
  return true;
}

